function getProfileAvatar(email=profileAccountEmail()){
  try{
    const normalized=String(email||'').trim().toLowerCase();
    const avatars=JSON.parse(localStorage.getItem('viziunea.profile-avatars.v1')||'{}')||{};
    const aliases=[normalized];
    if(normalized==='zametheea@demo.viziunea.ro')aliases.push('zametheea','zametheea popescu');
    if(normalized==='radu.calin@demo.viziunea.ro')aliases.push('radu','radu călin');
    return aliases.map(key=>avatars[key]).find(Boolean)||'';
  }catch{return '';}
}
