const exploreMetaObserver = new MutationObserver(() => {
  document.querySelectorAll('.premium-card-meta').forEach(meta => {
    const parts = meta.querySelectorAll('span');
    if (parts.length < 2) return;
    const normalizedCity = parts[0].textContent.replace(/^⌖\s*/, '').trim();
    if (parts[0].textContent !== normalizedCity) parts[0].textContent = normalizedCity;
    const city = parts[0].textContent.replace(/^⌖\s*/, '').trim();
    const value = parts[1].textContent.trim();
    const suffix = `· ${city}`;
    if (city && value.endsWith(suffix)) parts[1].textContent = value.slice(0, -suffix.length).trim();
  });
});
