async function hydrateFeedSocialState(){const key=`${currentUser?.id||'demo'}:${FEED_POSTS.map(post=>post.id||post.title).join('|')}`;if(socialHydrationKey===key)return;socialHydrationKey=key;try{const [saved,liked,interested]=await Promise.all([listSavedPostIds(currentUser),listPostLikeIds(currentUser),listPostInterestIds(currentUser)]);serverSavedPostIds=new Set(saved);serverLikedPostIds=new Set(liked);serverInterestedPostIds=new Set(interested);const commentEntries=await Promise.all(FEED_POSTS.map(async(post,index)=>[postPersistenceId(post,index),await listPostComments(postPersistenceId(post,index),currentUser)]));serverCommentsByPost=new Map(commentEntries.filter(([,comments])=>comments.length));if(isRealUser()&&saved.length){const records=getSavedFeedRecords();const now=new Date().toISOString();const indexes=saved.map(id=>FEED_POSTS.findIndex((post,index)=>postPersistenceId(post,index)===id)).filter(index=>index>=0);localStorage.setItem(FEED_SAVED_KEY,JSON.stringify([...new Set([...records.map(record=>record.index),...indexes])].map(index=>({index,savedAt:getSavedFeedRecords().find(record=>record.index===index)?.savedAt||now}))));}}catch(error){socialHydrationKey='';console.warn('Social data sync unavailable; keeping demo fallback',error);}}
