function enhanceFeedView(){if(path()!=='/feed')return;const page=app.querySelector('.feed-page');if(!page)return;page.classList.toggle('feed-create-mode',feedMode==='create');let toggle=page.querySelector('.feed-mode-toggle');if(!toggle){page.querySelector('.page-intro')?.insertAdjacentHTML('afterend','<div class="feed-mode-toggle" role="tablist"><button type="button" data-feed-mode="news">Noutăți</button><button type="button" data-feed-mode="create">Contribuie</button></div>');toggle=page.querySelector('.feed-mode-toggle');}let surface=page.querySelector('.community-surface');if(!surface){surface=document.createElement('section');surface.className='community-surface';const community=page.querySelector('.community-feed');if(community)community.before(surface);else page.append(surface);surface.append(toggle);const preferences=page.querySelector('.feed-preferences');const locationCard=page.querySelector('.feed-location');if(preferences)surface.append(preferences);if(locationCard)surface.append(locationCard);if(community)surface.append(community);}toggle.querySelectorAll('[data-feed-mode]').forEach(button=>{const selected=button.dataset.feedMode===feedMode;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});const intro=page.querySelector('.page-intro');if(intro)intro.textContent=feedMode==='create'?'Adu o idee, un proiect sau un context în ecosistem.':'Postări din comunitate, potrivite intereselor și zonei tale.';if(feedMode==='create'&&!page.querySelector('#create-post-panel')){toggle.insertAdjacentHTML('afterend',`<section class="create-post-card" id="create-post-panel"><span class="page-kicker">Postare nouă</span><h2>Ce vrei să aduci în comunitate?</h2><p>Postarea va fi verificată de un moderator înainte să devină vizibilă pentru ceilalți membri.</p><form id="create-post-form"><div class="create-post-grid"><label>Titlu<input name="title" required maxlength="180" placeholder="De exemplu: Caut partener pentru un atelier"></label><label>Tip<select name="entity_type"><option value="person">Om propus</option><option value="project">Proiect</option><option value="space">Loc / spațiu</option><option value="event">Eveniment</option><option value="opportunity">Oportunitate</option><option value="resource">Resursă</option></select></label><label>Oraș / locație<input name="city" value="${esc(demoFeed.city)}" placeholder="București, online sau adresă"></label><label>Când? <input name="event_date" type="date"></label><fieldset class="interest-checkboxes"><legend>Ce interese acoperă?</legend><div class="interest-checkbox-grid">${[...exploreCategories.map(([,label])=>label),'Resurse / informații'].map(label=>`<label><input type="checkbox" name="interests" value="${label}"><span>${label}</span></label>`).join('')}</div></fieldset><label>Tu ești reprezentantul? <select name="representation_type"><option value="self">Da</option><option value="on_behalf">Nu, însă vorbesc în numele lui/ei</option><option value="proposal">Nu, este doar o propunere</option></select></label><label class="create-post-wide">Cine este persoana / organizația? <input name="represented_name" placeholder="Nume, organizație sau inițiativă"></label><label>Contact preferat<select name="contact_method"><option value="platform">Mesaj pe platformă</option><option value="email">Email</option><option value="phone">Telefon</option><option value="whatsapp">WhatsApp</option><option value="website">Website</option></select></label><label>Detaliu de contact<input name="contact_value" placeholder="Email, număr, link sau username"></label><label class="create-post-wide">Descriere și informații relevante<textarea name="body" rows="6" required maxlength="5000" placeholder="Spune contextul, ce cauți și cum poate contribui comunitatea."></textarea></label></div><button class="account-cta" type="submit">Trimite spre moderare <span>→</span></button><p class="create-post-notice">${esc(feedNotice)}</p></form></section>`);}}
function enhanceFeedCityFilter(){if(path()!=='/feed'||feedMode==='create')return;const locationCard=app.querySelector('.feed-location>div');if(!locationCard)return;let select=locationCard.querySelector('[data-feed-city]');const cities=[...new Set(FEED_POSTS.map(post=>post.city).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ro'));if(!select){const current=demoFeed.city;locationCard.querySelector('strong')?.remove();locationCard.querySelector('small')?.remove();locationCard.insertAdjacentHTML('afterbegin',`<label for="feed-city">Oraș<select id="feed-city" name="city" data-feed-city><option value="">Toate orașele</option>${cities.map(city=>`<option value="${city}" ${city===current?'selected':''}>${city}</option>`).join('')}</select></label>`);select=locationCard.querySelector('[data-feed-city]');}if(select)select.value=demoFeed.city||'';}
function syncCreateContactField(){const form=app.querySelector('#create-post-form');const method=form?.querySelector('[name="contact_method"]');const field=form?.querySelector('[name="contact_value"]')?.closest('label');const type=form?.querySelector('[name="entity_type"]');const dateField=form?.querySelector('[name="event_date"]')?.closest('label');const notice=form?.querySelector('.create-post-notice');if(notice)notice.textContent=feedNotice;if(method&&field){field.hidden=method.value==='platform';if(method.value==='platform')field.querySelector('input').value='';}if(type&&dateField){dateField.hidden=type.value!=='event';if(type.value!=='event')dateField.querySelector('input').value='';}}
function syncCreateContactPlaceholder(){const form=app.querySelector('#create-post-form');const method=form?.querySelector('[name="contact_method"]');const input=form?.querySelector('[name="contact_value"]');if(!method||!input)return;const config={email:{type:'email',placeholder:'exemplu@domeniu.ro'},phone:{type:'tel',placeholder:'+40 7xx xxx xxx'},whatsapp:{type:'tel',placeholder:'+40 7xx xxx xxx'},website:{type:'url',placeholder:'https://site-ul-tau.ro'},platform:{type:'text',placeholder:''}}[method.value]||{type:'text',placeholder:'Email, număr, link sau username'};input.type=config.type;input.placeholder=config.placeholder;input.inputMode=config.type==='tel'?'tel':config.type==='email'?'email':config.type==='url'?'url':'text';}
