function enhanceContributionWizard(){if(path()!=='/feed'||feedMode!=='create')return;const form=app.querySelector('#create-post-form');const grid=form?.querySelector('.create-post-grid');if(!form||!grid||form.dataset.wizardReady)return;const byName=name=>grid.querySelector(`[name="${name}"]`)?.closest('label');const title=byName('title');const type=byName('entity_type');const city=byName('city');const date=byName('event_date');const interests=grid.querySelector('.interest-checkboxes');const representation=byName('representation_type');const contactMethod=byName('contact_method');const contactValue=byName('contact_value');const body=byName('body');const image=byName('image_file');const steps=[{label:'Ce aduci?',description:'Alege categoria care descrie cel mai bine contribuția ta.',items:[type]},{label:'Cum se numește?',description:'Dă-i un nume clar și spune pe scurt despre ce este vorba.',items:[title,body]},{label:'Unde și pentru cine?',description:'Adaugă locația, interesele și felul în care ești implicat.',items:[city,date,interests,representation,contactMethod,contactValue,image]}];grid.innerHTML='';const stepNodes=steps.map((definition,index)=>{const step=document.createElement('section');step.className='contribution-step';step.dataset.step=String(index);step.innerHTML=`<div class="contribution-step-heading"><span>Pasul ${index+1}</span><h3>${definition.label}</h3><p>${definition.description}</p></div>`;definition.items.filter(Boolean).forEach(item=>step.append(item));grid.append(step);return step;});const progress=document.createElement('div');progress.className='contribution-progress';progress.innerHTML=steps.map((step,index)=>`<div class="contribution-progress-step"><span data-step-dot="${index}">${index+1}</span><small>${step.label}</small></div>${index<steps.length-1?'<i></i>':''}`).join('');form.insertBefore(progress,grid);const submit=form.querySelector('.account-cta');const controls=document.createElement('div');controls.className='contribution-controls';const previous=document.createElement('button');previous.type='button';previous.className='contribution-previous';previous.textContent='← Înapoi';const next=document.createElement('button');next.type='button';next.className='account-cta contribution-next';next.innerHTML='Continuă <span>→</span>';controls.append(previous,next);form.insertBefore(controls,submit);if(submit)controls.append(submit);let current=0;const update=()=>{stepNodes.forEach((step,index)=>{step.hidden=index!==current;});progress.querySelectorAll('[data-step-dot]').forEach(dot=>dot.classList.toggle('selected',Number(dot.dataset.stepDot)===current));previous.hidden=current===0;next.hidden=current===stepNodes.length-1;if(submit)submit.hidden=current!==stepNodes.length-1;};const validate=()=>{const invalid=stepNodes[current].querySelector(':invalid');if(invalid){invalid.reportValidity();return false;}return true;};previous.addEventListener('click',()=>{current=Math.max(0,current-1);update();});next.addEventListener('click',()=>{if(!validate())return;current=Math.min(stepNodes.length-1,current+1);update();});form.dataset.wizardReady='true';update();}
function enhanceContributionInterestCards(){if(path()!=='/feed'||feedMode!=='create')return;const content={Oameni:['👥','Conexiuni','Găsește oameni și construiește împreună.'],Proiecte:['🧩','Proiecte','Idei care caută oameni și resurse.'],Experiențe:['🌿','Experiențe','Contexte de învățare și întâlnire.'],Evenimente:['📅','Evenimente','Ce se întâmplă în comunitate.'],Oportunități:['✨','Oportunități','Invitații, roluri și colaborări.'],Spații:['🏠','Spații','Locuri deschise pentru activare.'],'Resurse / informații':['📚','Resurse','Informații utile pentru oameni creativi.']};app.querySelectorAll('.interest-checkbox-grid label').forEach(label=>{if(label.dataset.cardReady)return;const input=label.querySelector('input');const value=input?.value;const data=content[value]||['✦',value,'Conținut relevant pentru comunitate.'];const span=label.querySelector('span');if(!span)return;span.innerHTML=`<b>${data[0]}</b><strong>${data[1]}</strong><i></i><small>${data[2]}</small>`;label.dataset.cardReady='true';});}
function enhanceCreateLocationField(){if(path()!=='/feed'||feedMode!=='create')return;const input=app.querySelector('#create-post-form [name="city"]');if(!input||input.dataset.locationReady)return;input.dataset.locationReady='true';input.setAttribute('autocomplete','street-address');input.setAttribute('data-location-autocomplete','true');const label=input.closest('label');if(!label)return;const suggestions=document.createElement('div');suggestions.className='location-suggestions';suggestions.hidden=true;label.append(suggestions);let timer;let controller;const close=()=>{suggestions.hidden=true;suggestions.innerHTML='';};input.addEventListener('input',()=>{clearTimeout(timer);controller?.abort();if(input.form){input.form.dataset.locationLabel=input.value;delete input.form.dataset.locationLatitude;delete input.form.dataset.locationLongitude;delete input.form.dataset.locationPlaceId;}if(input.value.trim().length<3){close();return;}timer=setTimeout(async()=>{controller=new AbortController();try{const results=await searchLocations(input.value,controller.signal);if(!results.length){close();return;}suggestions.innerHTML=results.map((result,index)=>`<button type="button" class="location-suggestion" data-location-index="${index}"><strong>${esc(result.label)}</strong>${result.city?`<small>${esc(result.city)}</small>`:''}</button>`).join('');suggestions.hidden=false;suggestions.querySelectorAll('[data-location-index]').forEach(button=>button.addEventListener('click',()=>{const result=results[Number(button.dataset.locationIndex)];input.value=result.label;input.form.dataset.locationLabel=result.label;input.form.dataset.locationLatitude=String(result.latitude);input.form.dataset.locationLongitude=String(result.longitude);input.form.dataset.locationPlaceId=result.placeId||'';close();}));}catch(error){if(error.name!=='AbortError')close();}},280);});document.addEventListener('click',event=>{if(!label.contains(event.target))close();});}
