const messageDistance=(city,origin=demoProfile.city)=>{if(!city||city==='Online')return 0;if(city===origin)return 0;const distances={'București':{'Cluj-Napoca':325,'Iași':390,'Brașov':185,'Sibiu':280},'Cluj-Napoca':{'București':325,'Iași':390,'Brașov':275,'Sibiu':180}};return distances[origin]?.[city]||distances.București?.[city]||999;};
const messageMembers=()=>ADMIN_MEMBERS.filter(member=>member.email!==currentUser?.email);
const messageIdentity=value=>String(value||'').trim().toLowerCase();
function memberForMessage(message){const current=messageIdentity(currentUser?.email||currentUser?.id);const from=messageIdentity(message.from||message.sender_id);const to=messageIdentity(message.to||message.recipient_id);const email=from===current?to:from;return ADMIN_MEMBERS.find(member=>messageIdentity(member.email)===email)||{name:message.fromName||message.toName||'Membru',email};}
function messageConversationMessages(email){const current=messageIdentity(currentUser?.email||currentUser?.id);const other=messageIdentity(email);return messagingData.filter(message=>{const from=messageIdentity(message.from||message.sender_id);const to=messageIdentity(message.to||message.recipient_id);return (from===current&&to===other)||(to===current&&from===other);});}
function renderMessages(){if(path()!=='/mesaje')return;app.innerHTML=messagesView();bind();}
function messagesView(){const members=messageMembers();const cities=[...new Set(members.map(member=>member.city))].sort((a,b)=>a.localeCompare(b,'ro'));const roles=[...new Set(members.flatMap(member=>member.roles))].sort();const interests=[...new Set(members.flatMap(member=>member.interests.split(', ')))].sort();const conversations=[...new Map(messagingData.map(message=>{const member=memberForMessage(message);return [messageIdentity(member.email),member];})).values()];const selected=members.find(member=>messageIdentity(member.email)===messageIdentity(messageTargetEmail))||conversations.find(member=>messageIdentity(member.email)===messageIdentity(messageTargetEmail))||conversations[0];const chat=selected?messageConversationMessages(selected.email):[];return `${navbar()}<main class="page messages-page"><div class="messages-heading"><div><span class="page-kicker">Comunicare</span><h1>Mesaje</h1><p class="page-intro">Găsește oameni din comunitate și continuă conversațiile într-un singur loc.</p></div><strong class="community-count">${members.length+1} membri în comunitate</strong></div><section class="messenger-layout"><aside class="conversation-sidebar"><header><h2>Conversațiile tale</h2><span>${conversations.length}</span></header><div class="conversation-list">${conversations.length?conversations.map(member=>`<button type="button" class="conversation-item ${selected?.email===member.email?'selected':''}" data-message-member="${esc(member.email)}"><span class="member-avatar">${esc(member.name[0])}</span><span><strong>${esc(member.name)}</strong><small>${esc(messageConversationMessages(member.email).at(-1)?.body||'Deschide conversația')}</small></span></button>`).join(''):'<div class="conversation-empty">Nu ai încă conversații.<br><small>Alege un membru de mai sus pentru a începe.</small></div>'}</div></aside><section class="chat-panel">${selected?`<header class="chat-header"><span class="member-avatar">${esc(selected.name[0])}</span><div><h2>${esc(selected.name)}</h2><small>${esc(selected.roles.join(' · '))} · ${esc(selected.city)}</small></div></header><div class="chat-messages">${chat.length?chat.map(message=>{const mine=messageIdentity(message.from||message.sender_id)===messageIdentity(currentUser?.email||currentUser?.id);return `<div class="chat-bubble ${mine?'mine':''}"><p>${esc(message.body)}</p><time>${new Date(message.created_at).toLocaleString('ro-RO')}</time></div>`;}).join(''):'<div class="chat-empty"><strong>Începe conversația cu ${esc(selected.name)}</strong><span>Trimite un mesaj și va apărea aici.</span></div>'}</div><form class="chat-composer" id="messenger-chat-form"><textarea name="body" rows="1" required placeholder="Scrie un mesaj..."></textarea><button type="submit" aria-label="Trimite mesajul">→</button></form>`:'<div class="chat-empty chat-empty-large"><span class="chat-empty-icon">✦</span><strong>Selectează o conversație</strong><span>Alege un membru sau o conversație din stânga pentru a începe să vorbești.</span></div>'}</section></section></main>${footer()}`;}
function notificationsView(){return `${navbar()}<main class="page notifications-page"><span class="page-kicker">Activitatea contului</span><h1>Notificări</h1><p class="page-intro">Aici vezi mesajele și activitatea care te privește.</p><section class="notification-list">${notificationData.length?notificationData.map(notification=>`<article class="notification-item"><span class="notification-dot"></span><div><strong>${esc(notification.title)}</strong><p>${esc(notification.body||'')}</p><small>${new Date(notification.created_at).toLocaleString('ro-RO')}</small></div></article>`).join(''):'<div class="feed-empty"><strong>Nu ai notificări noi.</strong></div>'}</section></main>${footer()}`;}
async function hydrateMessaging(){const key=`${currentUser?.id||''}:${path()}`;if(!currentUser)return;if(messagingHydratedKey===key){if(path()==='/mesaje'&&!app.querySelector('.messenger-layout')){app.innerHTML=messagesView();bind();}return;}messagingHydratedKey=key;try{if(path()==='/mesaje'){messagingData=(await listMessages(currentUser)).data;app.innerHTML=messagesView();}else if(path()==='/notificari'){notificationData=(await listNotifications(currentUser)).data;app.innerHTML=notificationsView();}bind();}catch(error){messagingHydratedKey='';console.warn('Messaging sync unavailable',error);}}
const shell=(title,cls='')=>{const directionKey=path().split('/').pop();const [intro,items]=PAGE_CONTENT[path()]|| (DIRECTION_CONTENT[directionKey]&&['Structura direcției',DIRECTION_CONTENT[directionKey]]) || ['Structură de pagină',['Conținutul acestei pagini va fi construit ulterior']];return `${navbar()}<main class="page ${cls}"><span class="page-kicker">Page shell</span><h1>${esc(title)}</h1><p class="page-intro">${esc(intro)}</p><ul class="page-outline">${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></main>${footer()}`;};
const exploreLocationOptions=(results,locations)=>{const counts=results.reduce((total,_,index)=>{const city=locations[index%locations.length];total[city]=(total[city]||0)+1;return total;},{});return `<option value="">Toate locațiile (${results.length})</option>${Object.entries(counts).map(([city,count])=>`<option value="${city}">${city} (${count})</option>`).join('')}`;};
function exploreView(){const active=exploreCategories.some(([id])=>id===location.hash.slice(1))?location.hash.slice(1):'oameni';const results=DEMO_RESULTS[active];const directions=['Artă','Educație','Turism','Servicii Creative','Intervenție Culturală'];const locations=['București','Cluj-Napoca','Iași','Brașov'];const periods=['Acum','Viitoare','Arhivă'];return `${navbar()}<main class="page explore-page"><span class="page-kicker">Page shell</span><h1>Explorează</h1><p class="page-intro">Ce există în ecosistem</p><div class="explore-pills" role="tablist">${exploreCategories.map(([id,label])=>`<a class="explore-pill ${id===active?'selected':''}" href="/exploreaza#${id}" role="tab" aria-selected="${id===active}">${label}</a>`).join('')}</div><section class="explore-filter-bar"><label>Direcție<select class="explore-filter" data-filter="direction"><option value="">Toate direcțiile</option>${directions.map(value=>`<option value="${value}" ${exploreFilters.direction===value?'selected':''}>${value}</option>`).join('')}</select></label><label>Locație<select class="explore-filter" data-filter="location">${exploreLocationOptions(results,locations).replace(`value="${exploreFilters.location}"`, `value="${exploreFilters.location}" selected`)}</select></label><label>Perioadă<select class="explore-filter" data-filter="period"><option value="">Toate perioadele</option>${periods.map(value=>`<option ${exploreFilters.period===value?'selected':''}>${value}</option>`).join('')}</select></label><button class="filter-reset" data-explore-reset type="button">Resetează</button><span class="filter-count" data-explore-count>${results.length} rezultate</span></section><section class="demo-results"><span class="page-kicker">Demo results · date fictive</span><h2>${esc(exploreCategories.find(([id])=>id===active)[1])}</h2><div class="result-grid">${results.map((item,index)=>`<article class="result-card" data-result data-direction="${directions[index%directions.length]}" data-location="${locations[index%locations.length]}" data-period="${periods[index%periods.length]}"><span>0${index+1}</span><strong>${esc(item.title)}</strong><b>${esc(item.meta)}</b><small>${esc(item.desc)}</small><button class="person-more" data-explore-detail="${active}" data-detail-index="${index}" type="button">Vezi mai multe <span>→</span></button></article>`).join('')}</div><p class="empty-explore" hidden>Nu există rezultate pentru combinația aleasă.</p></section></main>${footer()}`;}
function profileView(){const roles=['Creator','Trainer','Participant','Voluntar','Partner','Gazdă de spațiu'];const interests=['Artă','Educație','Experiențe','Turism','Evenimente','Proiecte','Spații'];const cities=['București','Cluj-Napoca','Iași','Brașov','Sibiu'];return `${navbar()}<main class="page profile-page"><span class="page-kicker">Page shell · Demo profile</span><section class="profile-hero"><div class="large-avatar">Z</div><div><h1>Zametheea</h1><p>zametheea@demo.viziunea.ro</p></div></section><section class="profile-selectors"><article><span class="page-kicker">Roluri</span><h2>Ce roluri te reprezintă?</h2><p>Selectează sau deselectează oricând rolurile care te reprezintă.</p><div class="profile-choices">${roles.map(role=>`<button class="profile-choice ${demoProfile.roles.includes(role)?'selected':''}" data-profile-type="roles" data-profile-value="${role}" type="button">${role}</button>`).join('')}</div></article><article><span class="page-kicker">Interese</span><h2>Ce te interesează?</h2><p>Alege domeniile pe care vrei să le urmărești în profilul tău.</p><div class="profile-choices">${interests.map(interest=>`<button class="profile-choice ${demoProfile.interests.includes(interest)?'selected':''}" data-profile-type="interests" data-profile-value="${interest}" type="button">${interest}</button>`).join('')}</div></article><article class="profile-location"><span class="page-kicker">Locație</span><h2>Care este orașul tău?</h2><p>Îl folosim ca punct de plecare pentru recomandările locale.</p><label>Oraș<select data-profile-city>${cities.map(city=>`<option ${city===demoProfile.city?'selected':''}>${city}</option>`).join('')}</select></label></article></section><section class="profile-structure"><article><span class="page-kicker">Identitate</span><h2>Profilul meu</h2><ul><li>Nume și date de contact</li><li>Despre mine</li></ul></article><article><span class="page-kicker">Prezență</span><h2>Despre mine</h2><ul><li>Scurtă prezentare</li><li>Oraș și disponibilitate</li><li>Linkuri publice</li></ul></article></section></main>${footer()}`;}
function feedView(){const choices=['Artă','Educație','Experiențe','Turism','Evenimente','Proiecte','Spații'];const radii=[10,25,50,100,250];const posts=FEED_POSTS.filter(post=>(!demoFeed.interests.length||demoFeed.interests.includes(post.interest))&&(post.distance===0||post.distance<=Number(demoFeed.radius)));return `${navbar()}<main class="page feed-page"><span class="page-kicker">Zona personală</span><h1>Feed</h1><p class="page-intro">Postări din comunitate, potrivite intereselor și zonei tale.</p><div class="feed-preferences">${choices.map(choice=>`<button class="feed-choice ${demoFeed.interests.includes(choice)?'selected':''}" data-feed-interest="${choice}" type="button">${choice}</button>`).join('')}</div><section class="feed-location"><div><span class="page-kicker">Recomandări locale</span><strong>${esc(demoFeed.city)}</strong><small>Oraș preluat automat din profil</small></div><label>Raza față de oraș<select data-feed-radius>${radii.map(radius=>`<option value="${radius}" ${Number(demoFeed.radius)===radius?'selected':''}>${radius} km</option>`).join('')}</select></label></section><section class="community-feed"><header><div><span class="page-kicker">Comunitatea ta</span><h2>${posts.length} ${posts.length===1?'postare relevantă':'postări relevante'}</h2></div><small>Date demonstrative</small></header><div class="feed-posts">${posts.length?posts.map(post=>`<article class="feed-post"><div class="feed-post-author"><span class="feed-post-avatar">${post.initial}</span><div><strong>${esc(post.author)}</strong><small>${esc(post.role)} · ${esc(post.time)}</small></div><span class="feed-post-distance">${post.distance?`${post.distance} km · `:''}${esc(post.city)}</span></div><div class="feed-post-content"><span class="feed-post-tag">${esc(post.interest)}</span><h3>${esc(post.title)}</h3><p>${esc(post.body)}</p></div><footer><button type="button">${esc(post.action)}</button><div><button type="button" aria-label="Salvează"></button><button type="button" aria-label="Distribuie">↗</button></div></footer></article>`).join(''):`<div class="feed-empty"><strong>Nu sunt încă postări pentru combinația aleasă.</strong><span>Extinde raza sau selectează încă un interes.</span></div>`}</div></section></main>${footer()}`;}
function authView(){return `<main class="auth-page"><section class="auth-card"><a class="site-logo" href="/admin">Viziunea<span>✳</span></a><span class="page-kicker">Comunitatea Viziunea · Demo</span><h1>Intră în cont</h1><p>Continuă cu profilul demo Zametheea pentru a vedea zona personală.</p><form id="auth-form"><label>Nume<input name="display_name" autocomplete="name" value="Zametheea"></label><label>Email<input name="email" type="email" autocomplete="email" required value="zametheea@demo.viziunea.ro"></label><button class="account-cta" type="submit">Continuă <span>→</span></button></form><p class="auth-message">${esc(authNotice)}</p></section></main>`;}
function optionCounts(values, field){return values.map(value=>{const count=ADMIN_MEMBERS.filter(member=>field==='interest'?member.interests.split(', ').includes(value):field==='role'?member.roles.includes(value):member[field]===value).length;return `<option value="${value}">${value} (${count})</option>`;}).join('');}
function compactDate(value){const months={ianuarie:'01',februarie:'02',martie:'03',aprilie:'04',mai:'05',iunie:'06',iulie:'07',august:'08',septembrie:'09',octombrie:'10',noiembrie:'11',decembrie:'12'};const match=String(value).match(/^(\d{1,2})\s+([^\s]+)\s+(\d{4})$/i);return match?`${match[1].padStart(2,'0')}.${months[match[2].toLowerCase()]||match[2]}.${match[3].slice(-2)}`:value;}
function adminView(){const roles=[...new Set(ADMIN_MEMBERS.flatMap(member=>member.roles))].sort();const cities=[...new Set(ADMIN_MEMBERS.map(member=>member.city))].sort();const interests=[...new Set(ADMIN_MEMBERS.flatMap(member=>member.interests.split(', ')))].sort();const visibleMembers=adminHasServerPage?ADMIN_MEMBERS:ADMIN_MEMBERS.slice((adminPage-1)*25,adminPage*25);const total=adminHasServerPage?adminTotal:ADMIN_MEMBERS.length;return `<header class="site-header admin-header"><a class="site-logo" href="/admin">Viziunea<span>✳</span></a><span class="admin-badge">ADMIN · DEMO DATABASE</span><a href="/" class="nav-link">Înapoi la site</a></header><main class="admin-shell"><div class="admin-heading"><div><span class="page-kicker">Admin · Members database</span><h1>Membrii Viziunea</h1><p>Identitate, roluri și activitate în comunitate.</p></div><button class="admin-action" type="button">+ Adaugă membru</button></div><div class="admin-stats"><div><span>Total membri</span><strong>${total}</strong></div><div><span>Activi</span><strong>${ADMIN_MEMBERS.filter(member=>member.status==='Activ').length}</strong></div><div><span>Roluri selectate</span><strong>${new Set(ADMIN_MEMBERS.flatMap(member=>member.roles)).size}</strong></div><div><span>Orașe</span><strong>${new Set(ADMIN_MEMBERS.map(member=>member.city)).size}</strong></div></div><section class="member-filters"><div class="filter-search"><span>⌕</span><input id="member-search" type="search" placeholder="Caută după nume sau email"></div><label>Rol<select id="member-role"><option value="">Toate rolurile (${total})</option>${optionCounts(roles,'role')}</select></label><label>Oraș<select id="member-city"><option value="">Toate orașele (${total})</option>${optionCounts(cities,'city')}</select></label><label>Status<select id="member-status"><option value="">Orice status (${total})</option>${optionCounts(['Activ','În așteptare'],'status')}</select></label><label>Interes<select id="member-interest"><option value="">Orice interes (${total})</option>${optionCounts(interests,'interest')}</select></label><button class="filter-reset" id="filter-reset" type="button">Resetează</button><span class="filter-count" id="filter-count">${visibleMembers.length} ${visibleMembers.length===1?'membru':'membri'}</span></section><section class="members-table"><div class="members-table-head"><h2>Toți membrii</h2><span>${adminHasServerPage?'Date Supabase · pagină '+adminPage:'Date demo · sincronizare bază de date ulterior'}</span></div><div class="members-table-scroll"><table><thead><tr><th>Membru</th><th>Roluri</th><th>Locație</th><th>Înregistrat</th><th>Ultima activitate</th><th>Status</th></tr></thead><tbody>${visibleMembers.map(member=>`<tr data-member-row data-name="${member.name.toLowerCase()}" data-email="${member.email.toLowerCase()}" data-roles="${member.roles.join('|')}" data-city="${member.city}" data-status="${member.status}" data-interests="${member.interests}"><td><div class="member-person"><span class="member-avatar">${member.name[0]}</span><div><strong>${member.name}</strong><small>${member.email}</small></div></div></td><td><div class="member-roles">${member.roles.map(role=>`<span>${role}</span>`).join('')}</div><small class="member-interests">${member.interests}</small></td><td>${member.city}</td><td><time title="${member.registered}">${compactDate(member.registered)}</time></td><td>${member.active}</td><td><span class="member-status ${member.status==='Activ'?'is-active':'is-pending'}">${member.status}</span></td></tr>`).join('')}</tbody></table></div>${total>25?`<nav class="admin-pagination"><button type="button" data-admin-page="${adminPage-1}" ${adminPage===1?'disabled':''}>← Anterior</button><span>Pagina ${adminPage} din ${Math.ceil(total/25)}</span><button type="button" data-admin-page="${adminPage+1}" ${adminPage>=Math.ceil(total/25)?'disabled':''}>Următoarea →</button></nav>`:''}</section></main>`;}
function profileHistoryView(){const roles=['Creator','Trainer','Participant','Voluntar','Partner','Gazdă de spațiu'];const interests=['Artă','Educație','Experiențe','Turism','Evenimente','Proiecte','Spații'];const cities=['București','Cluj-Napoca','Iași','Brașov','Sibiu'];const links=demoProfile.profileLinks&&typeof demoProfile.profileLinks==='object'?demoProfile.profileLinks:{};const social=[['facebook','Facebook','https://s.magecdn.com/social/tc-facebook.svg'],['instagram','Instagram','https://s.magecdn.com/social/tc-instagram.svg'],['linkedin','LinkedIn','https://s.magecdn.com/social/tc-linkedin.svg'],['website','Website','https://s.magecdn.com/social/tc-wordpress.svg']];const socialEditor=social.map(([key,label,icon])=>`<label class="profile-social-row"><span><input type="checkbox" data-profile-link-check="${key}" ${links[key]?'checked':''}><img src="${icon}" alt="">${label}</span><input type="url" data-profile-link="${key}" value="${esc(links[key]||'')}" placeholder="https://${key}.com/profilul-tău" ${links[key]?'':'hidden'}></label>`).join('');const method=demoProfile.profileContactMethod||'email';const profileIdentity=profileAccountEmail();const profileName=profileIdentity.includes('radu.calin')?'Radu Călin':'Zametheea Popescu';const ownPosts=FEED_POSTS.map((post,index)=>({post,index})).filter(({post})=>post.author_email?.toLowerCase()===profileIdentity||post.author===profileName||post.author?.toLowerCase()===profileName.split(' ')[0].toLowerCase());const ownPostsMarkup=ownPosts.length?ownPosts.map(({post,index})=>{const interested=interestedMembers(post,index);const likes=readFeedList(FEED_LIKES_KEY).filter(row=>row.post_id===feedPostId(post,index)).length;return `<article class="profile-post-crm" data-profile-post="${index}"><div class="profile-post-crm-heading"><div><span class="page-kicker">${esc(post.interest||'Comunitate')}</span><h3>${esc(post.title)}</h3><p>${esc(post.body)}</p></div><span class="profile-post-status">Publicată</span></div><div class="profile-post-crm-stats"><span><strong>${interested.length}</strong> interesați</span><span><strong>${likes}</strong> aprecieri</span><span>${esc(post.city||'Online')}</span></div><section class="profile-interest-crm"><header><strong>Cei interesați</strong><span>${interested.length}</span></header>${interested.length?`<ul>${interested.map(member=>`<li><span class="member-avatar">${esc((member.name||member.email||'M')[0])}</span><span><strong>${esc(member.name||member.email||'Membru Viziunea')}</strong><small>${esc(member.email||'')}</small></span>${member.email?`<button type="button" data-crm-message-email="${esc(member.email)}" data-crm-message-name="${esc(member.name||member.email)}">Scrie-i</button>`:''}</li>`).join('')}</ul>`:'<p>Încă nu există persoane interesate. Când cineva apasă „Sunt interesat”, apare aici.</p>'}</section></article>`}).join(''):'<div class="profile-crm-empty"><strong>Nu ai postări încă.</strong><span>Postările tale și oamenii interesați vor apărea aici.</span></div>';return `${navbar()}<main class="page profile-page"><section class="profile-hero"><div class="large-avatar">Z</div><div><h1>Zametheea</h1><p>zametheea@demo.viziunea.ro</p></div></section><nav class="profile-tabs" role="tablist"><button class="profile-tab is-active" type="button" data-profile-tab="profile-summary-card">Profilul meu</button><button class="profile-tab" type="button" data-profile-tab="profile-location">Locație</button><button class="profile-tab" type="button" data-profile-tab="profile-roles">Roluri</button><button class="profile-tab" type="button" data-profile-tab="profile-interests">Interese</button></nav><section class="profile-selectors" data-tabs-ready="true"><article class="profile-summary-card" data-editable="true"><span class="page-kicker">Profil</span><h2>Profilul meu</h2><div class="profile-edit-fields"><label>Scurtă prezentare<textarea data-profile-field="about" rows="3" placeholder="Spune câteva lucruri despre tine">${esc(demoProfile.profileAbout||'')}</textarea></label><div class="profile-availability"><label class="profile-checkbox-row"><input type="checkbox" data-profile-field="availability" ${demoProfile.profileAvailability?'checked':''}><span>Deschis(ă) pentru colaborări</span></label><textarea data-profile-field="availabilityDetails" rows="2" placeholder="Detalii opționale despre disponibilitate" ${demoProfile.profileAvailability?'':'hidden'}>${esc(demoProfile.profileAvailabilityDetails||'')}</textarea></div><div class="profile-links-editor" data-profile-links="true">${socialEditor}</div><div class="profile-contact-fields"><label>Date de contact<textarea data-profile-field="contact" rows="2" placeholder="Email, telefon sau alte date de contact">${esc(demoProfile.profileContact||'')}</textarea></label><label>Metodă preferată de contact<select data-profile-contact-method><option value="email" ${method==='email'?'selected':''}>Email</option><option value="whatsapp" ${method==='whatsapp'?'selected':''}>WhatsApp</option><option value="platform" ${method==='platform'?'selected':''}>Mesaj Viziunea</option></select></label><input type="tel" data-profile-contact-phone value="${esc(demoProfile.profileContactPhone||'')}" placeholder="Număr de telefon pentru WhatsApp" ${method==='whatsapp'?'':'hidden'}></div></div></article><article class="profile-location is-tab-hidden"><span class="page-kicker">Locație</span><h2>Care este orașul tău?</h2><p>Îl folosim ca punct de plecare pentru recomandările locale.</p><label>Oraș<select data-profile-city>${cities.map(city=>`<option ${city===demoProfile.city?'selected':''}>${city}</option>`).join('')}</select></label><label>Câți km de jur împrejur vrei să vezi?<select data-profile-radius><option value="50">50 km</option><option value="100" selected>100 km</option><option value="250">250 km</option><option value="500">500 km</option></select></label><label class="profile-defaults-choice"><input type="checkbox" data-profile-defaults ${demoProfile.useProfileDefaults?'checked':''}><span>Folosește orașul și raza ca filtre implicite.</span></label></article><article class="profile-roles is-tab-hidden"><span class="page-kicker">Roluri</span><h2>Ce roluri te reprezintă?</h2><div class="profile-choices">${roles.map(role=>`<button class="profile-choice ${demoProfile.roles.includes(role)?'selected':''}" data-profile-type="roles" data-profile-value="${role}" type="button">${role}</button>`).join('')}</div></article><article class="profile-interests is-tab-hidden"><span class="page-kicker">Interese</span><h2>Ce te interesează?</h2><div class="profile-choices">${interests.map(interest=>`<button class="profile-choice ${demoProfile.interests.includes(interest)?'selected':''}" data-profile-type="interests" data-profile-value="${interest}" type="button">${interest}</button>`).join('')}</div></article></section><section class="profile-posts-crm-section" id="postari"><header><div><span class="page-kicker">Activitatea ta</span><h2>Postările mele</h2><p>Un loc simplu ca să vezi cine se uită la ce construiești și să continui conversațiile.</p></div><strong>${ownPosts.length} ${ownPosts.length===1?'postare':'postări'}</strong></header><div class="profile-posts-crm-list">${ownPostsMarkup}</div></section></main>${footer()}`;}
function profilePostsView(){const profileIdentity=profileAccountEmail();const profileName=profileIdentity.includes('radu.calin')?'Radu Călin':'Zametheea Popescu';const ownPosts=FEED_POSTS.map((post,index)=>({post,index})).filter(({post})=>post.author_email?.toLowerCase()===profileIdentity||post.author===profileName||post.author?.toLowerCase()===profileName.split(' ')[0].toLowerCase());const postsMarkup=ownPosts.length?ownPosts.map(({post,index})=>{const interested=interestedMembers(post,index);const likes=readFeedList(FEED_LIKES_KEY).filter(row=>row.post_id===feedPostId(post,index)).length;return `<article class="profile-post-crm" data-profile-post="${index}"><div class="profile-post-crm-heading"><div><span class="page-kicker">${esc(post.interest||'Comunitate')}</span><h3>${esc(post.title)}</h3><p>${esc(post.body)}</p></div><span class="profile-post-status">Publicată</span></div><div class="profile-post-crm-stats"><span><strong>${interested.length}</strong> interesați</span><span><strong>${likes}</strong> aprecieri</span><span>${esc(post.city||'Online')}</span></div><section class="profile-interest-crm"><header><strong>Cei interesați</strong><span>${interested.length}</span></header>${interested.length?`<ul>${interested.map(member=>`<li><span class="member-avatar">${esc((member.name||member.email||'M')[0])}</span><span><strong>${esc(member.name||member.email||'Membru Viziunea')}</strong><small>${esc(member.email||'')}</small></span>${member.email?`<button type="button" data-crm-message-email="${esc(member.email)}" data-crm-message-name="${esc(member.name||member.email)}">Scrie-i</button>`:''}</li>`).join('')}</ul>`:'<p>Încă nu există persoane interesate. Când cineva apasă „Sunt interesat”, apare aici.</p>'}</section></article>`}).join(''):'<div class="profile-crm-empty"><strong>Nu ai postări încă.</strong><span>Postările tale și oamenii interesați vor apărea aici.</span></div>';return `${navbar()}<main class="page profile-posts-page"><header class="profile-posts-page-heading"><span class="page-kicker">Activitatea ta</span><h1>Postările mele</h1><p>Vezi ce ai publicat și continuă conversațiile cu oamenii interesați.</p><strong>${ownPosts.length} ${ownPosts.length===1?'postare':'postări'}</strong></header><section class="profile-posts-crm-list">${postsMarkup}</section></main>${footer()}`;}
function legacyRender(){document.body.classList.toggle('admin-mode',path()==='/admin');if(path()==='/admin')app.innerHTML=adminView();else if(path()==='/auth')app.innerHTML=authView();else if(path()==='/exploreaza')app.innerHTML=exploreView();else if(path()==='/profil')app.innerHTML=profileHistoryView();else if(path()==='/feed')app.innerHTML=feedView();else {const title=ROUTES[path()]||DIRECTIONS.find(([u])=>u===path())?.[1]||'Pagină';app.innerHTML=shell(title,path().slice(1).replaceAll('/','-')||'home');}bind();if(path()==='/admin'){enhanceAdminContacts();const header=app.querySelector('.members-table thead tr');if(header&&header.children[6]?.textContent==='Interese')header.insertBefore(header.children[6],header.children[2]);app.querySelectorAll('.members-table tbody tr').forEach(row=>{const cityCell=row.children[3];if(cityCell&&!cityCell.dataset.fullCity){const full=cityCell.textContent.trim();cityCell.dataset.fullCity=full;cityCell.innerHTML=`<span class="city-short" title="${full}">${full.slice(0,6)}…</span>`;}});compactAdminPills();syncAdminFilterControls();void hydrateAdminMembers();}if(path()==='/exploreaza')enhanceExploreFilters();}
function enhanceExploreFilters(){const bar=app.querySelector('.explore-filter-bar');if(!bar)return;if(!bar.querySelector('.explore-name-filter'))bar.insertAdjacentHTML('beforeend','<label class="explore-name-filter" for="explore-search">Opțional · caută după nume<input id="explore-search" name="search" class="explore-search" type="search" placeholder="Nume sau titlu"></label>');const saved=readExploreFilters();Object.assign(exploreFilters,demoProfile.useProfileDefaults?{...saved,location:demoProfile.city,distance:String(demoFeed.radius||100)}:saved);Object.entries(exploreFilters).forEach(([key,value])=>{const input=app.querySelector(`[data-filter="${key}"]`)||app.querySelector('.explore-search');if(input&&value)input.value=value;});}
function enhanceExplorePremiumCards(){if(path()!=='/exploreaza')return;const category=location.hash.slice(1)||'oameni';const cards=app.querySelectorAll('[data-result]');const icons={oameni:'◉',proiecte:'✦',experiente:'◌',evenimente:'◷',oportunitati:'↗',spatii:'⌂'};const tones={oameni:'sage',proiecte:'purple',experiente:'blue',evenimente:'gold',oportunitati:'terra',spatii:'lilac'};const authors=['Radu Călin','Zametheea Popescu','Mara Enache'];const eventDates=['10 octombrie 2026','24 octombrie 2026','10 ianuarie 2027'];cards.forEach((card,index)=>{if(card.dataset.premiumReady)return;const item=DEMO_RESULTS[category]?.[index];if(!item)return;const author=item.author_name||authors[index%authors.length];const role=item.author_role||(category==='oameni'?(item.meta?.split('·')[0]||'Membru'):'Membru Viziunea');const location=item.author_city||item.city||item.meta?.split('·').at(-1)?.trim()||'România';const meta=category==='evenimente'?eventDates[index%eventDates.length]:item.meta;const interest=meta?.split('·')[0]?.trim()||category;card.classList.add('premium-result-card',`tone-${tones[category]||'sage'}`);card.innerHTML=`<div class="premium-card-top"><span class="premium-card-icon">${icons[category]||'✦'}</span><span class="premium-card-index">0${index+1}</span></div><span class="premium-card-tag">${esc(interest)}</span><strong class="premium-card-title">${category==='oameni'?memberAvatarMarkup(item.email,item.title):''}${esc(item.title)}</strong><p class="premium-card-description">${esc(item.desc)}</p><div class="premium-card-meta"><span>⌖ ${esc(location)}</span><span>${esc(meta)}</span></div><button class="premium-card-author" data-explore-author="${esc(category)}" data-detail-index="${index}" type="button"><span class="member-avatar">${esc(author[0]||'M')}</span><span><strong>${esc(author)}</strong><small>${esc(role)}</small></span><b>Profil →</b></button><button class="person-more" data-explore-detail="${esc(category)}" data-detail-index="${index}" type="button">Vezi mai multe <span>→</span></button>`;card.dataset.premiumReady='true';});}
function polishExploreCards(){if(path()!=='/exploreaza')return;const category=location.hash.slice(1)||'oameni';const icons={oameni:'👥',proiecte:'🧩',experiente:'🌿',evenimente:'📅',oportunitati:'✨',spatii:'🏠'};app.querySelectorAll('.premium-result-card').forEach(card=>{const icon=card.querySelector('.premium-card-icon');if(icon)icon.textContent=icons[category]||'✨';if(category==='oameni')card.querySelector('.premium-card-author')?.remove();else card.querySelector('.premium-card-author b')?.remove();});const tones={oameni:'sage',proiecte:'purple',experiente:'blue',evenimente:'gold',oportunitati:'terra',spatii:'lilac'};app.querySelectorAll('.explore-pill').forEach(pill=>{if(pill.dataset.polished)return;const id=pill.getAttribute('href')?.split('#')[1]||'';pill.classList.add(`tone-${tones[id]||'sage'}`);pill.innerHTML=`<span class="explore-pill-icon">${icons[id]||'✨'}</span><span>${pill.textContent.trim()}</span>`;pill.dataset.polished='true';});}
const EXPLORE_CITY_DISTANCE={București:{București:0,'Cluj-Napoca':450,Iași:390,Brașov:185},'Cluj-Napoca':{București:450,'Cluj-Napoca':0,Iași:330,Brașov:270},Iași:{București:390,'Cluj-Napoca':330,Iași:0,Brașov:300},Brașov:{București:185,'Cluj-Napoca':270,Iași:300,Brașov:0}};
const EXPLORE_DEMO_AUTHORS=[{name:'Radu Călin',email:'radu.calin@demo.viziunea.ro',city:'București',role:'Creator'},{name:'Zametheea Popescu',email:'zametheea@demo.viziunea.ro',city:'București',role:'Creator · Participant'},{name:'Mara Enache',email:'mara.enache@demo.viziunea.ro',city:'Sibiu',role:'Gazdă de spațiu · Partner'}];
function enrichExploreResult(item,index){if(!item)return item;if(DEMO_RESULTS.oameni.includes(item)){item.author_name=item.title;item.author_email=item.email;item.author_city=item.meta?.split(' · ').at(-1);item.author_role=item.meta?.split(' · ')[0];return item;}const author=EXPLORE_DEMO_AUTHORS[index%EXPLORE_DEMO_AUTHORS.length];item.author_name ||= author.name;item.author_email ||= author.email;item.author_city ||= author.city;item.author_role ||= author.role;return item;}
function exploreDistance(city,origin){return EXPLORE_CITY_DISTANCE[origin]?.[city]??(city===origin?0:9999);}
function syncExploreDistanceFilter(){if(path()!=='/exploreaza')return;const locationSelect=app.querySelector('[data-filter="location"]');const distanceSelect=app.querySelector('[data-filter="distance"]');if(!locationSelect||!distanceSelect)return;const hasLocation=Boolean(locationSelect.value);distanceSelect.disabled=!hasLocation;if(!hasLocation){distanceSelect.value='';return;}if(!distanceSelect.value)distanceSelect.value='100';}
function updateExploreLocationCounts(query=''){const select=app.querySelector('[data-filter="location"]');if(!select)return;const cards=[...app.querySelectorAll('[data-result]')].filter(card=>!query||card.textContent.toLowerCase().includes(query));[...select.options].forEach((option,index)=>{const label=option.textContent.replace(/ \(\d+\)$/,'');const count=index===0?cards.length:cards.filter(card=>card.dataset.location===option.value).length;option.textContent=`${label} (${count})`;if(index>0){option.hidden=count===0;option.disabled=count===0;}});}
async function refreshExploreFromServer(){const active=exploreCategories.find(([id])=>id===location.hash.slice(1))?.[0]||'oameni';const kind={proiecte:'projects',spatii:'spaces',evenimente:'events'}[active];if(!kind)return false;const search=app.querySelector('.explore-search')?.value.trim()||'';const city=app.querySelector('[data-filter="location"]')?.value||'';const requestId=++exploreRequestId;try{const result=await listContent(kind,{page:1,pageSize:100,search,city});if(requestId!==exploreRequestId||result.source!=='supabase'||result.count===0)return false;DEMO_RESULTS[active]=result.data.map(item=>({title:item.title,meta:item.city||'În comunitate',desc:item.description||item.body||'',author_name:item.author_name,author_email:item.author_email,author_city:item.author_city,author_role:item.author_role}));render();const nextSearch=app.querySelector('.explore-search');const nextCity=app.querySelector('[data-filter="location"]');if(nextSearch)nextSearch.value=search;if(nextCity)nextCity.value=city;return true;}catch(error){if(error?.code!=='PGRST205')console.warn('Explore filter sync unavailable; using local fallback',error);return false;}}
function hasActiveCommunityAccount(){return Boolean(currentUser&&(String(currentUser.id||'').startsWith('demo:')||currentUser.status==='active'||currentUser.user_metadata?.status==='active'));}
function openMessageComposer(item){const dialog=document.createElement('dialog');dialog.className='message-composer';dialog.innerHTML=`<form method="dialog"><button class="detail-close" value="cancel" aria-label="Închide">×</button><span class="page-kicker">Mesaj pentru ${esc(item.title)}</span><h2>Începe o conversație</h2><textarea name="body" rows="6" required placeholder="Scrie un mesaj pentru ${esc(item.title)}..."></textarea><p class="message-composer-notice"></p><button class="admin-action" value="send">Trimite mesajul <span>→</span></button></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const body=new FormData(event.target).get('body');try{await sendMessage({from:currentUser,to:{id:item.id||`demo:${item.email}`,email:item.email,user_metadata:{full_name:item.title}},body});dialog.querySelector('.message-composer-notice').textContent='Mesaj trimis. Radu va avea o notificare când intră în cont.';event.target.querySelector('textarea').value='';}catch(error){dialog.querySelector('.message-composer-notice').textContent=error.message||'Mesajul nu a putut fi trimis.';}});dialog.querySelector('.detail-close')?.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>dialog.remove());}
app.addEventListener('click',event=>{const button=event.target.closest?.('[data-crm-message-email]');if(!button)return;openMessageComposer({title:button.dataset.crmMessageName,email:button.dataset.crmMessageEmail});});function openExploreDetail(category,index){const item=DEMO_RESULTS[category]?.[index];if(!item)return;const dialog=document.createElement('dialog');dialog.className='explore-detail-dialog';if(!currentUser){dialog.innerHTML=`<button class="detail-close" type="button" aria-label="Închide">×</button><span class="page-kicker">Acces pentru membri</span><h2>Creează-ți un cont pentru a vedea mai multe</h2><p>Profilurile complete, datele de contact, resursele și detaliile comunității sunt disponibile membrilor Viziunea.</p><div class="access-steps"><span><b>1</b> Îți creezi profilul</span><span><b>2</b> Un moderator Viziunea îl validează</span><span><b>3</b> Primești acces la comunitate și beneficii</span></div><button class="admin-action detail-register" type="button">Creează contul</button>`;}else if(!hasActiveCommunityAccount()){dialog.innerHTML=`<button class="detail-close" type="button" aria-label="Închide">×</button><span class="page-kicker">Cont în curs de validare</span><h2>Un moderator verifică profilul tău</h2><p>După validare vei putea accesa profiluri complete, contacte, resurse și celelalte beneficii ale comunității.</p><button class="admin-action detail-close-secondary" type="button">Am înțeles</button>`;}else{const type=exploreCategories.find(([id])=>id===category)?.[1]||'Detaliu';dialog.innerHTML=`<button class="detail-close" type="button" aria-label="Închide">×</button><span class="page-kicker">${esc(type)} · profil complet</span><div class="detail-identity">${memberAvatarMarkup(item.email,item.title)}<div><h2>${esc(item.title)}</h2><b>${esc(item.meta)}</b><button class="result-author detail-author" data-explore-author="${category}" data-detail-index="${index}" type="button">Publicat de ${esc(item.author_name||'Membru Viziunea')}</button></div></div><p>${esc(item.desc)}</p><dl><div><dt>Disponibilitate</dt><dd>Deschis pentru conexiuni și colaborări în comunitate</dd></div><div><dt>Interese comune</dt><dd>Artă, educație și proiecte locale</dd></div><div><dt>Activitate</dt><dd>Membru activ · răspunde de obicei în 1–2 zile</dd></div></dl><button class="admin-action" data-message-to="${esc(item.email||item.author_email||'')}" type="button">Trimite un mesaj</button>`;}document.body.append(dialog);dialog.showModal();dialog.querySelectorAll('.detail-close,.detail-close-secondary').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.querySelector('[data-message-to]')?.addEventListener('click',()=>{dialog.close();openMessageComposer({title:item.author_name||item.title,email:item.author_email||item.email});});dialog.querySelector('.detail-register')?.addEventListener('click',()=>{dialog.close();go('/auth?intent=register');});dialog.addEventListener('close',()=>dialog.remove());}
function openMemberEditor(member,row){const dialog=document.createElement('dialog');dialog.className='member-editor';dialog.innerHTML=`<form method="dialog"><button class="editor-close" value="cancel" aria-label="Închide">×</button><span class="page-kicker">Editează membru</span><h2>${member.name}</h2><label>Status<select name="status"><option ${member.status==='Activ'?'selected':''}>Activ</option><option ${member.status==='În așteptare'?'selected':''}>În așteptare</option><option>Dezaprobat</option></select></label><label>Notă internă<textarea name="note" rows="4" placeholder="Adaugă o notă despre acest membru...">${member.note||member.admin_note||''}</textarea></label><button class="admin-action" value="save">Salvează modificările</button></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.target);const nextStatus=data.get('status');const nextNote=String(data.get('note')||'').trim();try{if(member.id&&!String(member.id).startsWith('m-'))await updateMember(member.id,{status:nextStatus,note:nextNote});member.status=nextStatus;member.note=nextNote;saveAdminMember(member.email,{status:nextStatus,note:nextNote});row.dataset.status=member.status;const badge=row.querySelector('.member-status');badge.textContent=member.status;badge.className=`member-status ${member.status==='Activ'?'is-active':member.status==='În așteptare'?'is-pending':'is-rejected'}`;const avatar=row.querySelector('.member-avatar');avatar.querySelector('.member-note')?.remove();if(member.note)avatar.insertAdjacentHTML('beforeend',`<span class="member-note" title="${member.note.replace(/"/g,'&quot;')}">✎</span>`);dialog.close();}catch(error){dialog.querySelector('.admin-action').textContent='Eroare · încearcă din nou';}});dialog.addEventListener('close',()=>dialog.remove());}
function enhanceModerationCardDetails(){if(path()!=='/admin')return;app.querySelectorAll('.moderation-card').forEach(card=>{if(card.dataset.detailsReady)return;const post=adminPosts.find(item=>String(item.id)===String(card.dataset.moderationPost));if(!post)return;const author=post.author_name||'Membru Viziunea';const authorEmail=post.author_email||'';const interests=(post.interests||[post.interest]).filter(Boolean);const statusClass=post.status==='pending'?'is-pending':post.status==='published'?'is-approved':'is-rejected';const statusLabel=post.status==='pending'?'În moderare':post.status==='published'?'Aprobată':'Dezaprobată';const image=post.image_url?`<img class="moderation-card-image" src="${esc(post.image_url)}" alt="Imagine pentru ${esc(post.title||'propunere')}" loading="lazy">`:'';const authorMember=ADMIN_MEMBERS.find(member=>member.email===authorEmail||member.name===author);card.innerHTML=`${image}<div class="moderation-card-content"><div class="moderation-card-top"><span class="moderation-status ${statusClass}">${statusLabel}</span><time>${post.created_at?new Date(post.created_at).toLocaleDateString('ro-RO'):''}</time></div><button type="button" class="moderation-author" data-moderation-author="${esc(authorEmail)}"><span class="member-avatar">${esc((authorMember?.name||author)[0]||'M')}</span><span><strong>${esc(authorMember?.name||author)}</strong><small>${esc(authorMember?.email||authorEmail||'Membru Viziunea')} · autorul propunerii</small></span><b>Vezi profilul →</b></button><h3>${esc(post.represented_name||post.title||'Fără titlu')}</h3>${post.represented_name?`<span class="moderation-project-title">${esc(post.title||'Postare')}</span>`:''}<p>${esc(post.body||post.description||'')}</p><div class="moderation-meta"><span>${esc(post.entity_type||'Postare')} · ${esc(post.city||'Online')}</span><span>${esc(interests.join(' · ')||'Fără interese selectate')}</span>${post.contact_method&&post.contact_method!=='platform'?`<span>${esc(post.contact_method)} · ${esc(post.contact_value||'')}</span>`:''}</div>${post.status==='pending'?`<div class="moderation-actions"><button type="button" data-moderation-action="published" data-post-id="${esc(post.id)}">Aprobă</button><button type="button" data-moderation-action="rejected" data-post-id="${esc(post.id)}">Dezaprobă</button></div>`:''}</div>`;card.dataset.detailsReady='true';});}
function enhanceAdminModeration(){if(path()!=='/admin')return;const section=app.querySelector('.admin-feed-moderation');if(!section||section.dataset.controlsReady)return;const counts={all:adminPosts.length,pending:adminPosts.filter(post=>post.status==='pending').length,published:adminPosts.filter(post=>post.status==='published').length,rejected:adminPosts.filter(post=>post.status==='rejected').length};const heading=section.querySelector('.admin-section-heading');const list=section.querySelector('.moderation-list');if(!heading||!list)return;heading.insertAdjacentHTML('afterend',`<div class="moderation-overview"><button type="button" class="moderation-filter is-selected" data-moderation-filter="pending"><strong>${counts.pending}</strong><span>Propuneri noi</span><small>Necesită decizie</small></button><button type="button" class="moderation-filter" data-moderation-filter="published"><strong>${counts.published}</strong><span>Acceptate</span><small>Vizibile în Feed</small></button><button type="button" class="moderation-filter" data-moderation-filter="rejected"><strong>${counts.rejected}</strong><span>Dezaprobate</span><small>Istoric moderare</small></button><button type="button" class="moderation-filter" data-moderation-filter="all"><strong>${counts.all}</strong><span>Toate</span><small>Vezi tot</small></button></div><div class="moderation-filter-note">${counts.pending?'Începe cu propunerile noi care așteaptă verificarea.':'Nu există propuneri noi în așteptare.'}</div>`);const active=counts.pending?'pending':'all';list.querySelectorAll('.moderation-card').forEach(card=>{card.dataset.moderationStatus=card.querySelector('.moderation-status')?.classList.contains('is-pending')?'pending':card.querySelector('.moderation-status')?.classList.contains('is-approved')?'published':'rejected';card.hidden=card.dataset.moderationStatus!==active;});section.dataset.controlsReady='true';}
function enhanceAdminPriority(){if(path()!=='/admin'||app.querySelector('.admin-priority'))return;const heading=app.querySelector('.admin-heading');if(!heading)return;const newMembers=ADMIN_MEMBERS.filter(member=>member.status==='În așteptare').length;const newPosts=adminPosts.filter(post=>post.status==='pending').length;const section=document.createElement('section');section.className='admin-priority';section.innerHTML=`<div class="admin-priority-heading"><span class="page-kicker">Acum · de verificat</span><h2>Priorități</h2><p>Tot ce a apărut nou și așteaptă atenția ta, într-o singură privire.</p></div><button type="button" class="admin-priority-card ${newMembers?'has-items':''}" data-admin-priority="members"><span class="priority-icon">♙</span><span><strong>${newMembers} ${newMembers===1?'membru nou':'membri noi'}</strong><small>Validare acces în comunitate</small></span><b>→</b></button><button type="button" class="admin-priority-card ${newPosts?'has-items':''}" data-admin-priority="posts"><span class="priority-icon">✦</span><span><strong>${newPosts} ${newPosts===1?'postare nouă':'postări noi'}</strong><small>Moderare Feed</small></span><b>→</b></button>`;heading.after(section);}
