app.addEventListener('change',event=>{if(path()!=='/feed'||!event.target.matches('#create-post-image'))return;const file=event.target.files?.[0];const preview=app.querySelector('[data-create-image-preview]');if(!preview)return;if(!file){preview.hidden=true;preview.removeAttribute('src');return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){event.target.value='';preview.hidden=true;preview.removeAttribute('src');feedNotice='Alege o imagine JPG, PNG sau WebP de maximum 10 MB.';enhanceFeedView();return;}preview.src=URL.createObjectURL(file);preview.hidden=false;});
app.addEventListener('change',event=>{if(path()!=='/feed'||!event.target.matches('[data-feed-city]'))return;demoFeed.city=event.target.value;saveFeedDemo();void saveFeedToSupabase(demoFeed,currentUser).catch(error=>console.warn('Feed location sync failed',error));render();});
app.addEventListener('click',event=>{if(path()!=='/mesaje')return;const button=event.target.closest?.('[data-message-member]');if(!button)return;messageTargetEmail=button.dataset.messageMember;renderMessages();app.querySelector('.chat-composer textarea')?.focus();});
app.addEventListener('input',event=>{if(path()!=='/mesaje'||!event.target.matches('[data-message-search]'))return;const query=event.target.value.trim().toLowerCase();let visible=0;app.querySelectorAll('[data-message-members] [data-message-member]').forEach(card=>{const show=!query||card.dataset.name.includes(query);card.hidden=!show;if(show)visible++;});const count=app.querySelector('[data-message-result-count]');if(count)count.textContent=visible;const empty=app.querySelector('[data-message-empty]');if(empty)empty.hidden=visible>0;});
app.addEventListener('change',event=>{if(path()!=='/mesaje'||!event.target.matches('[data-message-filter]'))return;const filters={};app.querySelectorAll('[data-message-filter]').forEach(select=>filters[select.dataset.messageFilter]=select.value);let visible=0;app.querySelectorAll('[data-message-members] [data-message-member]').forEach(card=>{const show=(!filters.city||card.dataset.city===filters.city)&&(!filters.distance||Number(card.dataset.distance)<=Number(filters.distance))&&(!filters.role||card.dataset.roles.split('|').includes(filters.role))&&(!filters.interest||card.dataset.interests.split(', ').includes(filters.interest));card.hidden=!show;if(show)visible++;});const count=app.querySelector('[data-message-result-count]');if(count)count.textContent=visible;const empty=app.querySelector('[data-message-empty]');if(empty)empty.hidden=visible>0;});
app.addEventListener('submit',async event=>{if(path()!=='/mesaje'||!event.target.matches('#messenger-chat-form'))return;event.preventDefault();const recipient=ADMIN_MEMBERS.find(member=>member.email===messageTargetEmail);const body=new FormData(event.target).get('body');if(!recipient)return;try{await sendMessage({from:currentUser,to:{id:recipient.id||`demo:${recipient.email}`,email:recipient.email,user_metadata:{full_name:recipient.name}},body});messagingData=(await listMessages(currentUser)).data;renderMessages();}catch(error){event.target.insertAdjacentHTML('afterend',`<p class="chat-error">${esc(error.message||'Mesajul nu a putut fi trimis.')}</p>`);}});
function applyMessageDirectoryFilters(){if(path()!=='/mesaje')return;const values={};app.querySelectorAll('[data-message-filter]').forEach(select=>values[select.dataset.messageFilter]=select.value);const query=app.querySelector('[data-message-search]')?.value.trim().toLowerCase()||'';let visible=0;app.querySelectorAll('[data-message-members] [data-message-member]').forEach(card=>{const show=(!query||card.dataset.name.includes(query))&&(!values.city||messageDistance(card.dataset.city,values.city)<=Number(values.distance||9999))&&(!values.distance||messageDistance(card.dataset.city,values.city||demoProfile.city)<=Number(values.distance))&&(!values.role||card.dataset.roles.split('|').includes(values.role))&&(!values.interest||card.dataset.interests.split(', ').includes(values.interest));card.hidden=!show;if(show)visible++;});const count=app.querySelector('[data-message-result-count]');if(count)count.textContent=visible;const empty=app.querySelector('[data-message-empty]');if(empty)empty.hidden=visible>0;}
app.addEventListener('input',event=>{if(path()==='/mesaje'&&(event.target.matches('[data-message-search]')))applyMessageDirectoryFilters();});
app.addEventListener('change',event=>{if(path()==='/mesaje'&&event.target.matches('[data-message-filter]'))applyMessageDirectoryFilters();});
app.addEventListener('click',async event=>{if(path()!=='/admin')return;const button=event.target.closest?.('[data-moderation-action]');if(!button)return;button.disabled=true;try{await updatePostStatus(button.dataset.postId,button.dataset.moderationAction);adminPosts=(await listModerationPosts()).data;const section=app.querySelector('.admin-feed-moderation');section?.remove();enhanceAdminPosts();}catch(error){button.disabled=false;console.warn('Feed moderation update failed',error);}});
app.addEventListener('click',event=>{if(path()!=='/admin')return;const button=event.target.closest?.('[data-moderation-author]');if(!button)return;const post=adminPosts.find(item=>String(item.author_email||'')===button.dataset.moderationAuthor)||adminPosts.find(item=>String(item.author_name||'')===button.querySelector('strong')?.textContent);if(post)openAuthorProfile({author:post.author_name,email:post.author_email,role:'Membru Viziunea',interest:(post.interests||[post.interest]).filter(Boolean).join(' · '),city:post.city});});
app.addEventListener('click',event=>{if(path()!=='/admin')return;const filter=event.target.closest?.('[data-moderation-filter]');if(!filter)return;const section=filter.closest('.admin-feed-moderation');if(!section)return;const value=filter.dataset.moderationFilter;section.querySelectorAll('[data-moderation-filter]').forEach(button=>button.classList.toggle('is-selected',button===filter));section.querySelectorAll('.moderation-card').forEach(card=>{card.hidden=value!=='all'&&card.dataset.moderationStatus!==value;});const note=section.querySelector('.moderation-filter-note');if(note)note.textContent=value==='pending'?'Propunerile noi care așteaptă verificarea.':value==='published'?'Postările acceptate și vizibile în Feed.':value==='rejected'?'Propunerile dezaprobate, păstrate în istoric.':'Toate propunerile, indiferent de status.';});
app.addEventListener('click',event=>{if(path()!=='/admin')return;const priority=event.target.closest?.('[data-admin-priority]');if(!priority)return;const target=priority.dataset.adminPriority==='members'?'.admin-onboarding':'.admin-feed-moderation';app.querySelector(target)?.scrollIntoView({behavior:'smooth',block:'start'});});
const FEED_SAVED_KEY='viziunea.feed.saved.v1';
const FEED_INTERESTED_KEY='viziunea.feed.interested.v1';
const FEED_LIKES_KEY='viziunea.feed.likes.v1';
function readFeedList(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[];}catch{return [];}}
function writeFeedList(key,value){localStorage.setItem(key,JSON.stringify(value));}
function feedIdentity(){return String(currentUser?.email||currentUser?.id||'guest').toLowerCase();}
function feedPostId(post,index){return String(post?.id||`demo-feed-${index}`);}
function interestedMembers(post,index){return readFeedList(FEED_INTERESTED_KEY).filter(row=>row.post_id===feedPostId(post,index));}
function interestedListMarkup(post,index){const members=interestedMembers(post,index);return `<div class="feed-interested-list"><strong>Interesați de această postare (${members.length})</strong>${members.length?`<ul>${members.map(member=>`<li><button type="button" class="interested-member-link" data-interested-member="${esc(member.name||member.email||'Membru Viziunea')}" data-interested-email="${esc(member.email||'')}">${esc(member.name||member.email||'Membru Viziunea')}</button></li>`).join('')}</ul>`:'<p>Încă nu s-a înscris nimeni.</p>'}</div>`;}
const FEED_SEEN_KEY='viziunea.feed.seen.v1';
function feedViewerKey(){return String(currentUser?.email||currentUser?.id||'guest').toLowerCase();}
function getSeenFeedRecords(){try{const rows=JSON.parse(localStorage.getItem(FEED_SEEN_KEY)||'[]');return Array.isArray(rows)?rows.filter(row=>row&&row.user===feedViewerKey()&&(Boolean(row.postId)||Number.isInteger(row.index))):[];}catch{return [];}}
function markFeedSeen(index){const rows=[];try{const stored=JSON.parse(localStorage.getItem(FEED_SEEN_KEY)||'[]');if(Array.isArray(stored))rows.push(...stored);}catch{}const user=feedViewerKey();const postId=feedPostId(FEED_POSTS[index],index);const next=rows.filter(row=>!(row.user===user&&(row.postId===postId||(!row.postId&&row.index===index))));next.push({user,index,postId,seenAt:new Date().toISOString()});localStorage.setItem(FEED_SEEN_KEY,JSON.stringify(next));}
function resetFeedSeen(){let rows=[];try{const stored=JSON.parse(localStorage.getItem(FEED_SEEN_KEY)||'[]');if(Array.isArray(stored))rows=stored;}catch{}localStorage.setItem(FEED_SEEN_KEY,JSON.stringify(rows.filter(row=>row?.user!==feedViewerKey())));}
function feedPublishedAt(post){if(post?.created_at&&!Number.isNaN(new Date(post.created_at).getTime()))return new Date(post.created_at).getTime();const label=String(post?.time||'').toLowerCase();const relative=label.match(/acum\s+(\d+)\s+(min|or[ăe]|zil[ea])/);if(relative){const unit=relative[2].startsWith('min')?60_000:relative[2].startsWith('or')?3_600_000:86_400_000;return Date.now()-Number(relative[1])*unit;}if(label.startsWith('ieri'))return Date.now()-86_400_000;return Date.now();}
function feedPostIsInRange(post){if(!demoFeed.city||!post.city)return true;const distance=exploreDistance(post.city,demoFeed.city);return distance<=Number(demoFeed.radius||100);}
function currentFeedNews(){const seen=new Set(getSeenFeedRecords().map(row=>row.postId||feedPostId(FEED_POSTS[row.index],row.index)));const weekAgo=Date.now()-7*24*60*60*1000;const rendered=new Set([...app.querySelectorAll('.feed-post[data-feed-index]')].map(card=>Number(card.dataset.feedIndex)));return FEED_POSTS.map((post,index)=>({post,index})).filter(({post,index})=>rendered.has(index)&&(!demoFeed.interests.length||feedPostInterests(post).some(interest=>demoFeed.interests.includes(interest)))&&feedPostIsInRange(post)&&feedPublishedAt(post)>=weekAgo&&!seen.has(feedPostId(post,index))).sort((a,b)=>feedPublishedAt(b.post)-feedPublishedAt(a.post)||a.index-b.index);}
function feedHistoryRecords(){return getSeenFeedRecords().sort((a,b)=>new Date(b.seenAt||0)-new Date(a.seenAt||0)).map(record=>{const index=record.postId?FEED_POSTS.findIndex((post,position)=>feedPostId(post,position)===record.postId):record.index;return {record,post:FEED_POSTS[index],index};}).filter(item=>item.post);}
function feedHistoryDay(value){const date=new Date(value||Date.now());const today=new Date();const yesterday=new Date();yesterday.setDate(today.getDate()-1);const key=date.toLocaleDateString('ro-RO');if(key===today.toLocaleDateString('ro-RO'))return 'Azi';if(key===yesterday.toLocaleDateString('ro-RO'))return 'Ieri';return date.toLocaleDateString('ro-RO',{day:'numeric',month:'long',year:'numeric'});}
function renderFeedHistory(){const section=app.querySelector('.feed-history');if(!section)return;const records=feedHistoryRecords();let previousDay='';const items=records.map(({post,index,record},position)=>{const day=feedHistoryDay(record.seenAt);const dayLabel=day===previousDay?'':`<div class="feed-history-day">${day}</div>`;previousDay=day;return `${dayLabel}<button type="button" class="feed-history-item" data-feed-history-post="${index}"><span class="feed-history-number">${position+1}</span><span><strong>${esc(post.title)}</strong><small>${esc(post.author||'Membru Viziunea')} · ${esc(post.city||'Online')} · văzut ${new Date(record.seenAt||Date.now()).toLocaleTimeString('ro-RO',{hour:'2-digit',minute:'2-digit'})}</small></span><span aria-hidden="true">→</span></button>`;}).join('');section.hidden=false;section.innerHTML=`<header><div><span class="page-kicker">Istoricul tău</span><h2>Postări văzute</h2></div><button type="button" class="feed-history-close" data-feed-history-close>Ascunde</button></header>${records.length?`<div class="feed-history-list">${items}</div>`:'<p class="feed-history-empty">Nu ai parcurs încă nicio postare.</p>'}`;}
function enhanceFeedCarousel(){if(path()!=='/feed'||feedMode==='create')return;const posts=app.querySelector('.feed-posts');if(!posts||posts.dataset.carouselReady)return;posts.dataset.carouselReady='true';const queue=currentFeedNews();let active=0,transitioning=false,controls;const renderCarousel=()=>{const news=queue;const finished=active>=news.length;const header=app.querySelector('.community-feed header');if(header){const heading=header.querySelector('h2');if(heading)heading.textContent=(!finished&&news.length)?`${news.length} ${news.length===1?'noutate':'noutăți'} disponibile`:'Ai văzut toate noutățile';const meta=header.querySelector('small');if(meta)meta.textContent=(!finished&&news.length)?'Swipe dreapta pentru următoarea noutate':'Mărește distanța pentru mai multe noutăți sau alege alt oraș.';}posts.querySelectorAll('.feed-post').forEach(card=>{const index=Number(card.dataset.feedIndex);const position=news.findIndex(item=>item.index===index);card.hidden=finished||position!==active;card.classList.toggle('feed-carousel-active',!finished&&position===active);});let empty=posts.querySelector('.feed-carousel-empty');if(finished||!news.length){if(!empty){empty=document.createElement('div');empty.className='feed-carousel-empty';posts.append(empty);}empty.innerHTML='<span class="feed-carousel-icon">✓</span><strong>Ai văzut toate noutățile din aria ta.</strong><p>Mărește distanța pentru mai multe noutăți sau alege alt oraș.</p><button type="button" class="feed-history-cta" data-feed-history-open>Vezi istoricul postărilor <span>→</span></button><button type="button" class="feed-demo-refresh" data-feed-reset-seen>Reafișează noutățile demo</button>';}else empty?.remove();controls=app.querySelector('.feed-carousel-controls');if(!controls){controls=document.createElement('div');controls.className='feed-carousel-controls';posts.after(controls);controls.addEventListener('click',event=>{if(event.target.closest('[data-feed-next]'))next();if(event.target.closest('[data-feed-prev]'))previous();});}controls.innerHTML=!finished&&news.length?`<button type="button" data-feed-prev ${active===0?'disabled':''}>← Înapoi</button><span>${active+1} / ${news.length}</span><button type="button" data-feed-next>Următoarea <span>→</span></button>`:'';};const next=()=>{if(transitioning||active>=queue.length)return;const currentIndex=queue[active].index;const currentCard=[...posts.querySelectorAll('.feed-post')].find(card=>Number(card.dataset.feedIndex)===currentIndex);transitioning=true;currentCard?.classList.add('feed-card-exit-left');setTimeout(()=>{markFeedSeen(currentIndex);active+=1;renderCarousel();const incoming=[...posts.querySelectorAll('.feed-post')].find(card=>!card.hidden);incoming?.classList.add('feed-card-enter-left');requestAnimationFrame(()=>incoming?.classList.remove('feed-card-enter-left'));setTimeout(()=>{transitioning=false;},280);},220);};const previous=()=>{if(transitioning||active===0)return;active-=1;renderCarousel();const incoming=[...posts.querySelectorAll('.feed-post')].find(card=>!card.hidden);incoming?.classList.add('feed-card-enter-left');requestAnimationFrame(()=>incoming?.classList.remove('feed-card-enter-left'));};let startX=0;posts.addEventListener('touchstart',event=>{startX=event.changedTouches[0].clientX;},{passive:true});posts.addEventListener('touchend',event=>{if(event.changedTouches[0].clientX-startX>70)next();if(startX-event.changedTouches[0].clientX>70)previous();},{passive:true});renderCarousel();}
app.addEventListener('click',event=>{if(path()!=='/feed')return;const openHistory=event.target.closest?.('[data-feed-history-open]');if(openHistory){let section=app.querySelector('.feed-history');if(!section){section=document.createElement('section');section.className='feed-history';app.querySelector('.feed-carousel-controls')?.after(section);}renderFeedHistory();enhanceFeedHistoryItems();return;}const closeHistory=event.target.closest?.('[data-feed-history-close]');if(closeHistory){closeHistory.closest('.feed-history').hidden=true;return;}const historyPost=event.target.closest?.('[data-feed-history-post]');if(historyPost){const post=FEED_POSTS[Number(historyPost.dataset.feedHistoryPost)];if(post)openFeedPostDetail(post);}});
function getSavedFeedRecords(){try{const saved=JSON.parse(localStorage.getItem(FEED_SAVED_KEY)||'[]');return Array.isArray(saved)?saved.map(item=>typeof item==='number'?{index:item,savedAt:new Date().toISOString()}:item).filter(item=>Number.isInteger(item.index)):[];}catch{return [];}}
function getSavedFeedIndexes(){return getSavedFeedRecords().map(item=>item.index);}
function isSavedFeedIndex(index){return getSavedFeedIndexes().includes(index)||serverSavedPostIds.has(postPersistenceId(FEED_POSTS[index],index));}
function setSavedFeedIndexes(indexes){const previous=getSavedFeedRecords();const now=new Date().toISOString();localStorage.setItem(FEED_SAVED_KEY,JSON.stringify([...new Set(indexes)].map(index=>({index,savedAt:previous.find(item=>item.index===index)?.savedAt||now}))));syncSavedNavCount();}
function syncSavedNavCount(){const count=getSavedFeedIndexes().length;document.querySelectorAll('.saved-nav-link').forEach(badge=>{badge.querySelector('.saved-nav-badge').textContent=count>9?'9+':count;badge.querySelector('.saved-nav-badge').classList.toggle('is-empty',count===0);badge.firstChild.textContent=count?'♥':'♡';badge.classList.toggle('has-saved-items',count>0);});}
function enhanceFeedSaved(){if(path()!=='/feed'||feedMode==='create')return;const page=app.querySelector('.feed-page');const posts=page?.querySelectorAll('.feed-post');if(!page||!posts?.length)return;posts.forEach(post=>{const index=Number(post.dataset.feedIndex);const save=post.querySelector('[aria-label="Salvează"]');const share=post.querySelector('[aria-label="Distribuie"]');if(save){save.dataset.feedAction='save';save.textContent='♥';save.classList.toggle('is-saved',Number.isInteger(index)&&index>=0&&isSavedFeedIndex(index));}if(share)share.dataset.feedAction='share';});let saved=page.querySelector('.saved-feed-section');if(!saved){saved=document.createElement('section');saved.className='saved-feed-section';page.querySelector('.community-feed')?.after(saved);}const indexes=getSavedFeedIndexes().filter(index=>FEED_POSTS[index]);saved.innerHTML=`<header><div><span class="page-kicker">La îndemână</span><h2>Postări salvate</h2></div><strong>${indexes.length} ${indexes.length===1?'postare':'postări'}</strong></header>${indexes.length?`<div class="saved-feed-list">${indexes.map(index=>{const post=FEED_POSTS[index];return `<article class="saved-feed-item" data-saved-post="${index}"><div><strong>${esc(post.title)}</strong><small>${esc(post.author)} · ${esc(post.city)}</small></div><button type="button" data-remove-saved="${index}" aria-label="Elimină din salvate">×</button></article>`;}).join('')}</div>`:'<p class="saved-feed-empty">Postările cărora le dai inimă apar aici ca să le găsești rapid mai târziu.</p>'}`;}
function openFeedShare(post){const dialog=document.createElement('dialog');dialog.className='feed-share-dialog';const members=ADMIN_MEMBERS.filter(member=>member.email!==currentUser?.email);const linkUrl=`${location.origin}${BASE_PATH}/feed`;const preset=`Îți trimit această postare din Viziunea: „${post.title}”\n\n${post.body}\n\nVezi postarea în Feed: ${linkUrl}`;dialog.innerHTML=`<form method="dialog"><button class="detail-close" value="cancel" aria-label="Închide">×</button><span class="page-kicker">Distribuie postarea</span><h2>${esc(post.title)}</h2><p class="feed-share-preview">${esc(post.body)}</p><label>Mesajul tău<textarea name="share_body" rows="6">${esc(preset)}</textarea></label><div class="feed-share-options"><button type="button" data-share-copy>Copiază linkul</button><a href="https://wa.me/?text=${encodeURIComponent(preset)}" target="_blank" rel="noopener">WhatsApp</a><a href="mailto:?subject=${encodeURIComponent(`Postare Viziunea: ${post.title}`)}&body=${encodeURIComponent(preset)}">Email</a></div><div class="feed-share-member"><label>Trimite unui membru Viziunea<select name="recipient"><option value="">Alege un membru...</option>${members.map(member=>`<option value="${esc(member.email)}">${esc(member.name)} · ${esc(member.city)}</option>`).join('')}</select></label><button type="button" class="admin-action" data-share-member>Trimite mesajul <span>→</span></button></div><p class="feed-share-notice"></p></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-share-copy]')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(linkUrl);dialog.querySelector('.feed-share-notice').textContent='Link copiat.';}catch{dialog.querySelector('.feed-share-notice').textContent=linkUrl;}});dialog.querySelector('[data-share-member]')?.addEventListener('click',async()=>{const email=dialog.querySelector('[name="recipient"]').value;const member=members.find(item=>item.email===email);if(!member){dialog.querySelector('.feed-share-notice').textContent='Alege un membru.';return;}try{await sendMessage({from:currentUser,to:{id:member.id||`demo:${member.email}`,email:member.email,user_metadata:{full_name:member.name}},body:dialog.querySelector('[name="share_body"]').value});dialog.querySelector('.feed-share-notice').textContent=`Postarea a fost trimisă lui ${member.name}.`;dialog.querySelector('[name="recipient"]').value='';}catch(error){dialog.querySelector('.feed-share-notice').textContent=error.message||'Mesajul nu a putut fi trimis.';}});dialog.addEventListener('close',()=>dialog.remove());}
app.addEventListener('click',event=>{if(path()!=='/feed')return;const remove=event.target.closest?.('[data-remove-saved]');if(remove){const index=Number(remove.dataset.removeSaved);setSavedFeedIndexes(getSavedFeedIndexes().filter(item=>item!==index));serverSavedPostIds.delete(postPersistenceId(FEED_POSTS[index],index));void togglePostSave(currentUser,postPersistenceId(FEED_POSTS[index],index),false).catch(error=>console.warn('Save removal failed',error));enhanceFeedSaved();return;}const action=event.target.closest?.('[data-feed-action]');if(!action)return;const card=action.closest('.feed-post');const index=Number(card?.dataset.feedIndex);const post=FEED_POSTS[index];if(!post)return;if(action.dataset.feedAction==='save'){const saved=isSavedFeedIndex(index);const next=!saved;setSavedFeedIndexes(next?[...getSavedFeedIndexes(),index]:getSavedFeedIndexes().filter(item=>item!==index));if(next)serverSavedPostIds.add(postPersistenceId(post,index));else serverSavedPostIds.delete(postPersistenceId(post,index));void togglePostSave(currentUser,postPersistenceId(post,index),next).catch(error=>console.warn('Save sync failed',error));enhanceFeedSaved();}else if(action.dataset.feedAction==='share')openFeedShare(post);});
document.addEventListener('click',event=>{if(path()!=='/feed')return;const action=event.target.closest?.('[data-feed-action="like"],[data-feed-action="interested"]');if(!action)return;event.preventDefault();const card=action.closest('.feed-post');const rawIndex=Number(card?.dataset.feedIndex);const index=Number.isInteger(rawIndex)&&rawIndex>=0?rawIndex:[...app.querySelectorAll('.feed-post')].indexOf(card);const post=FEED_POSTS[index];if(!post)return;const postId=feedPostId(post,index);const kind=action.dataset.feedAction;const key=kind==='like'?FEED_LIKES_KEY:FEED_INTERESTED_KEY;const identity=feedIdentity();const localRows=readFeedList(key);const serverRows=kind==='like'?serverLikedPostIds:serverInterestedPostIds;const persistedPost=Boolean(isRealUser()&&/^[0-9a-f-]{36}$/i.test(postId));const existing=persistedPost?serverRows.has(postId):localRows.some(row=>row.post_id===postId&&row.profile_id===identity);const next=!existing;if(persistedPost){if(kind==='like')void togglePostLike(currentUser,postId,next).then(()=>{next?serverLikedPostIds.add(postId):serverLikedPostIds.delete(postId);}).catch(error=>console.warn('Like sync failed',error));else void togglePostInterest(currentUser,postId,next).then(()=>{next?serverInterestedPostIds.add(postId):serverInterestedPostIds.delete(postId);}).catch(error=>console.warn('Interest sync failed',error));}else{const filtered=localRows.filter(row=>!(row.post_id===postId&&row.profile_id===identity));if(next)filtered.unshift({post_id:postId,profile_id:identity,name:currentUser?.name||currentUser?.user_metadata?.full_name||currentUser?.email||'Membru Viziunea',email:currentUser?.email||'',created_at:new Date().toISOString()});writeFeedList(key,filtered);}if(next&&kind==='interested'&&currentUser){const author=ADMIN_MEMBERS.find(member=>member.name===post.author);const authorId=post.author_id||author?.id;const recipient=authorId&&!String(authorId).startsWith('demo:')?{id:authorId,email:author?.email||'',user_metadata:{full_name:author?.name||post.author}}:author&&{...author,id:author.id||`demo:${author.email}`,user_metadata:{full_name:author.name}};if(recipient&&recipient.email!==currentUser.email)void notifyPostInterest({from:currentUser,to:recipient,postId,postTitle:post.title}).then(syncUnreadNavBadges).catch(error=>console.warn('Interest notification unavailable',error));}action.classList.toggle('is-active',next);if(kind==='like')action.textContent=next?'🤩':'🙂';else action.textContent=next?'Te-ai înscris':'Sunt interesat';if(kind==='interested')action.setAttribute('aria-label',next?'Ești pe lista de interesați':'Înscrie-te pe lista de interesați');});
function syncFeedIndexes(){if(path()!=='/feed')return;app.querySelectorAll('.feed-post').forEach(post=>{const title=post.querySelector('h3')?.textContent.trim();const index=FEED_POSTS.findIndex(item=>item.title===title);if(index>=0)post.dataset.feedIndex=index;});}
function ensureSavedFeedPanel(){if(path()!=='/feed'||feedMode==='create')return;const page=app.querySelector('.feed-page');if(!page||page.querySelector('.saved-feed-section'))return;const section=document.createElement('section');section.className='saved-feed-section';section.innerHTML='<header><div><span class="page-kicker">La îndemână</span><h2>Postări salvate</h2></div><strong>0 postări</strong></header><p class="saved-feed-empty">Postările cărora le dai inimă apar aici ca să le găsești rapid mai târziu.</p>';page.querySelector('.community-feed')?.after(section);}
function commentMentionMembers(body){const tokens=body.match(/@[\p{L}0-9._-]+/gu)||[];return ADMIN_MEMBERS.filter(member=>tokens.some(token=>{const handle=token.slice(1).toLocaleLowerCase('ro');return member.name.toLocaleLowerCase('ro').split(/\s+/)[0]===handle||member.email.split('@')[0].toLocaleLowerCase()===handle;}));}
function renderCommentTree(comments,parentId=null,depth=0){return comments.filter(comment=>(comment.parentId||comment.parent_id||null)===parentId).map(comment=>`<article class="feed-comment ${depth?'is-reply':''}" data-comment-id="${esc(comment.id)}"><span class="feed-comment-avatar">${esc((comment.authorName||'Membru Viziunea')[0]||'M')}</span><div class="feed-comment-body"><div><strong>${esc(comment.authorName||'Membru Viziunea')}</strong><time>${new Date(comment.created_at).toLocaleString('ro-RO')}</time></div><p>${esc(comment.body).replace(/(@[\p{L}0-9._-]+)/gu,'<b>$1</b>')}</p><button type="button" data-comment-reply="${esc(comment.id)}">Răspunde</button>${renderCommentTree(comments,comment.id,depth+1)}</div></article>`).join('');}
function normalizeServerComment(comment){const member=ADMIN_MEMBERS.find(item=>item.id===comment.author_id);return {...comment,authorName:member?.name||currentUser?.user_metadata?.full_name||'Membru Viziunea',parentId:comment.parent_id||null};}
function enhanceFeedComments(){if(path()!=='/feed'||feedMode==='create')return;app.querySelectorAll('.feed-post').forEach(post=>{const index=Number(post.dataset.feedIndex);if(!Number.isInteger(index)||index<0)return;let section=post.querySelector('.feed-comments');if(!section){section=document.createElement('section');section.className='feed-comments';post.append(section);}const comments=serverCommentsByPost.get(postPersistenceId(FEED_POSTS[index],index))?.map(normalizeServerComment)||listComments(`demo-feed-${index}`);section.innerHTML=`<div class="feed-comments-heading"><strong>${comments.length} ${comments.length===1?'comentariu':'comentarii'}</strong></div>${comments.length?`<div class="feed-comment-list">${renderCommentTree(comments)}</div>`:''}<form class="feed-comment-form" data-comment-form data-post-index="${index}"><textarea name="body" rows="1" required placeholder="Scrie un comentariu..."></textarea><button type="submit">Comentează</button></form>`;});}
app.addEventListener('click',event=>{if(path()!=='/feed')return;const reply=event.target.closest?.('[data-comment-reply]');if(!reply)return;const comment=reply.closest('.feed-post')?.querySelector('[data-comment-form]');if(!comment)return;comment.dataset.parentId=reply.dataset.commentReply;const textarea=comment.querySelector('textarea');textarea.placeholder='Răspunde la acest comentariu...';textarea.focus();});
app.addEventListener('submit',async event=>{if(path()!=='/feed'||!event.target.matches('[data-comment-form]'))return;event.preventDefault();const form=event.target;const body=String(new FormData(form).get('body')||'').trim();const index=Number(form.dataset.postIndex);const post=FEED_POSTS[index];if(!post)return;try{const mentions=commentMentionMembers(body);const parentId=form.dataset.parentId||null;const postId=postPersistenceId(post,index);if(isRealUser()){const comment=await addPostComment({postId,authorId:currentUser.id,body,parentId},currentUser);serverCommentsByPost.set(postId,[...(serverCommentsByPost.get(postId)||[]),comment]);}else{addComment({postKey:`demo-feed-${index}`,author:currentUser,body,parentId,mentions:mentions.map(member=>member.email)});}await Promise.all(mentions.map(member=>notifyMention({from:currentUser,to:{id:member.id||`demo:${member.email}`,email:member.email,user_metadata:{full_name:member.name}},body,postTitle:post.title})));app.querySelectorAll('.feed-comments').forEach(section=>section.remove());enhanceFeedComments();}catch(error){form.insertAdjacentHTML('afterend',`<p class="feed-comment-error">${esc(error.message||'Comentariul nu a putut fi trimis.')}</p>`);}});
function feedPostInterests(post){return Array.isArray(post.interests)&&post.interests.length?post.interests:[post.interest].filter(Boolean);}
function syncLikeConfirmation(button,active){let label=button.previousElementSibling;if(active){if(!label?.classList.contains('feed-like-confirmation')){label=document.createElement('span');label.className='feed-like-confirmation';label.textContent='Îmi place';button.before(label);}}else if(label?.classList.contains('feed-like-confirmation'))label.remove();}
function enhanceFeedInterestCounts(){if(path()!=='/feed'||feedMode==='create')return;app.querySelectorAll('.feed-choice').forEach(button=>{const label=button.dataset.feedInterest;if(button.textContent!==label)button.textContent=label;});const likes=readFeedList(FEED_LIKES_KEY);const interested=readFeedList(FEED_INTERESTED_KEY);app.querySelectorAll('.feed-post').forEach((card,index)=>{const post=FEED_POSTS[Number(card.dataset.feedIndex??index)];const postId=feedPostId(post,Number(card.dataset.feedIndex??index));const like=card.querySelector('[data-feed-action="like"]');const interest=card.querySelector('[data-feed-action="interested"]');const persistedPost=Boolean(isRealUser()&&/^[0-9a-f-]{36}$/i.test(postId));const liked=persistedPost?serverLikedPostIds.has(postId):likes.some(row=>row.post_id===postId&&row.profile_id===feedIdentity());const isInterested=persistedPost?serverInterestedPostIds.has(postId):interested.some(row=>row.post_id===postId&&row.profile_id===feedIdentity());if(like){like.textContent=liked?'🤩':'🙂';like.classList.toggle('is-active',liked);like.setAttribute('aria-pressed',String(liked));}if(interest){interest.classList.toggle('is-active',isInterested);const label=isInterested?'Te-ai înscris':'Sunt interesat';if(interest.textContent!==label)interest.textContent=label;interest.setAttribute('aria-pressed',String(isInterested));}});}
