async function openNotificationsPanel(trigger) {
  if (!currentUser) return;
  document.querySelector('.saved-dropdown-panel')?.remove();
  const existing = document.querySelector('.notifications-dropdown-panel');
  if (existing) { existing.remove(); return; }
  const result = await listNotifications(currentUser);
  const notifications = result.data || [];
  const unread = notifications.filter(notification => !notification.read && !notification.read_at);
  const panel = document.createElement('div');
  panel.className = 'notifications-dropdown-panel';
  const rect = trigger.getBoundingClientRect();
  panel.style.top = `${rect.bottom + 8}px`;
  panel.style.right = `${Math.max(16, window.innerWidth - rect.right)}px`;
  let showOlder = false;
  const recent = notification => Date.now() - new Date(notification.created_at).getTime() <= 7 * 24 * 60 * 60 * 1000;
  const render = () => {
    const visible = showOlder ? notifications.filter(recent) : notifications.filter(notification => !notification.read && !notification.read_at);
    const items = visible.map(notification => `<button type="button" class="notification-item ${notification.read || notification.read_at ? '' : 'is-unread'}" data-notification-id="${esc(notification.id || '')}" data-notification-type="${esc(notification.type || '')}" data-notification-sender="${esc(notification.sender_email || '')}"><span class="notification-dot"></span><span><strong>${esc(notification.title)}</strong><p>${esc(notification.body || '')}</p><small>${new Date(notification.created_at).toLocaleString('ro-RO')}</small></span></button>`).join('');
    const empty = `<div class="feed-empty"><strong>${showOlder ? 'Nu ai notificări din ultimele 7 zile.' : 'Nu ai notificări noi.'}</strong></div>`;
    const olderButton = !showOlder && notifications.some(recent) ? '<button type="button" class="notifications-older-toggle" data-notifications-older>Vezi notificări mai vechi</button>' : '';
    panel.innerHTML = `<div class="notifications-panel-heading"><div><span class="page-kicker">Activitatea contului</span><h2>Notificări</h2></div><button type="button" data-notifications-close aria-label="Închide">×</button></div><p class="notifications-panel-intro">Mesaje și activitate importantă pentru tine.</p><section class="notification-list">${items || empty}</section>${olderButton}`;
    panel.querySelector('[data-notifications-close]')?.addEventListener('click', () => panel.remove());
    panel.querySelector('[data-notifications-older]')?.addEventListener('click', () => { showOlder = true; render(); });
    panel.querySelectorAll('[data-notification-type]').forEach(item => item.addEventListener('click', () => {
      if (item.dataset.notificationType === 'interest') {
        void markNotificationRead(item.dataset.notificationId, currentUser).finally(() => { panel.remove(); syncUnreadNavBadges(); go('/feed'); });
        return;
      }
      if (item.dataset.notificationType !== 'message') return;
      const member = ADMIN_MEMBERS.find(candidate => candidate.email === item.dataset.notificationSender) || ADMIN_MEMBERS.find(candidate => item.querySelector('strong')?.textContent.includes(candidate.name) || item.querySelector('strong')?.textContent.includes(candidate.name.split(' ')[0]));
      messageTargetEmail = member?.email || item.dataset.notificationSender;
      void Promise.all([markNotificationRead(item.dataset.notificationId, currentUser), markConversationRead(messageTargetEmail, currentUser)]).finally(() => { panel.remove(); syncUnreadNavBadges(); go('/mesaje'); });
    }));
  };
  document.body.append(panel);
  render();
  if (unread.length) void Promise.all(unread.map(notification => markNotificationRead(notification.id, currentUser))).finally(syncUnreadNavBadges);
}
app.addEventListener('click',event=>{const trigger=event.target.closest?.('[data-notifications-trigger]');if(!trigger)return;event.preventDefault();event.stopImmediatePropagation();void openNotificationsPanel(trigger);},true);
function openSavedFeedPanel(trigger){document.querySelector('.notifications-dropdown-panel')?.remove();const existing=document.querySelector('.saved-dropdown-panel');if(existing){existing.remove();return;}const panel=document.createElement('div');panel.className='saved-dropdown-panel';const rect=trigger.getBoundingClientRect();panel.style.top=`${rect.bottom+8}px`;panel.style.left=`${Math.max(16,rect.left-30)}px`;const categories=[...new Set(getSavedFeedIndexes().flatMap(index=>feedPostInterests(FEED_POSTS[index]||{})))];let category='all';let recent=false;const render=()=>{const records=getSavedFeedRecords().filter(record=>FEED_POSTS[record.index]).filter(record=>category==='all'||feedPostInterests(FEED_POSTS[record.index]).includes(category)).filter(record=>!recent||Date.now()-new Date(record.savedAt).getTime()<=7*24*60*60*1000);panel.innerHTML=`<div class="saved-panel-heading"><div><span class="page-kicker">La îndemână</span><h2>Postările tale salvate</h2></div><button type="button" data-saved-close aria-label="Închide">×</button></div><div class="saved-panel-filters"><button type="button" class="${category==='all'?'selected':''}" data-saved-category="all">Toate (${getSavedFeedRecords().length})</button>${categories.map(item=>`<button type="button" class="${category===item?'selected':''}" data-saved-category="${esc(item)}">${esc(item)} (${getSavedFeedRecords().filter(record=>feedPostInterests(FEED_POSTS[record.index]||{}).includes(item)).length})</button>`).join('')}<button type="button" class="${recent?'selected':''}" data-saved-recent>Ultimele 7 zile</button></div><div class="saved-panel-list">${records.length?records.sort((a,b)=>new Date(b.savedAt)-new Date(a.savedAt)).map(record=>{const post=FEED_POSTS[record.index];return `<article class="saved-panel-item" data-saved-post="${record.index}"><strong>${esc(post.title)}</strong><button type="button" class="saved-panel-author" data-feed-author="${record.index}">${esc(post.author)}</button><small>${esc(post.city)} · ${new Date(record.savedAt).toLocaleDateString('ro-RO')}</small><span>${esc(feedPostInterests(post).join(' · '))}</span></article>`;}).join(''):'<div class="saved-panel-empty">Nu există postări salvate pentru filtrul ales.</div>'}</div>`;panel.querySelector('[data-saved-close]')?.addEventListener('click',()=>panel.remove());panel.querySelectorAll('[data-saved-category]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.savedCategory;render();}));panel.querySelector('[data-saved-recent]')?.addEventListener('click',()=>{recent=!recent;render();});};document.body.append(panel);render();}
app.addEventListener('click',event=>{const trigger=event.target.closest?.('[data-saved-trigger]');if(!trigger)return;event.preventDefault();event.stopImmediatePropagation();openSavedFeedPanel(trigger);},true);
document.addEventListener('click',event=>{
  if(event.target.closest('.saved-dropdown-panel,.notifications-dropdown-panel,[data-saved-trigger],[data-notifications-trigger]'))return;
  document.querySelector('.saved-dropdown-panel')?.remove();
  document.querySelector('.notifications-dropdown-panel')?.remove();
});
function addSavedPanelHearts(panel){panel.querySelectorAll('.saved-panel-item').forEach(item=>{if(item.querySelector('[data-saved-toggle]'))return;item.insertAdjacentHTML('beforeend',`<button type="button" class="saved-panel-heart" data-saved-toggle="${item.dataset.savedPost}" aria-label="Elimină sau păstrează postarea salvată">♥</button>`);});}
new MutationObserver(()=>document.querySelectorAll('.saved-dropdown-panel').forEach(addSavedPanelHearts)).observe(document.body,{childList:true,subtree:true});
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-saved-toggle]');if(!button)return;event.preventDefault();event.stopPropagation();const index=Number(button.dataset.savedToggle);const saved=isSavedFeedIndex(index);const next=!saved;setSavedFeedIndexes(next?[...getSavedFeedIndexes(),index]:getSavedFeedIndexes().filter(item=>item!==index));if(next)serverSavedPostIds.add(postPersistenceId(FEED_POSTS[index],index));else serverSavedPostIds.delete(postPersistenceId(FEED_POSTS[index],index));void togglePostSave(currentUser,postPersistenceId(FEED_POSTS[index],index),next).catch(error=>console.warn('Save sync failed',error));button.textContent=next?'♥':'♡';button.classList.toggle('is-empty',!next);button.setAttribute('aria-label',next?'Elimină din postările salvate':'Păstrează postarea salvată');});
function syncUnreadNavBadges(){if(!currentUser)return;const counts=getDemoUnreadCounts(currentUser);document.querySelectorAll('.nav-message-badge').forEach(badge=>{badge.textContent=counts.messages>9?'9+':counts.messages;badge.classList.toggle('is-empty',counts.messages===0);});document.querySelectorAll('.nav-notification-badge').forEach(badge=>{badge.textContent=counts.notifications>9?'9+':counts.notifications;badge.classList.toggle('is-empty',counts.notifications===0);});}
app.addEventListener('click',event=>{const messageLink=event.target.closest?.('a[href$="/mesaje"]');if(messageLink){event.preventDefault();event.stopImmediatePropagation();messageTargetEmail='';go('/mesaje');return;}if(path()!=='/mesaje')return;const memberButton=event.target.closest?.('[data-message-member]');if(!memberButton)return;event.preventDefault();event.stopImmediatePropagation();messageTargetEmail=memberButton.dataset.messageMember;void markConversationRead(messageTargetEmail,currentUser).finally(()=>{syncUnreadNavBadges();});renderMessages();app.querySelector('.chat-composer textarea')?.focus();},true);
function openAuthorProfile(post){const member=ADMIN_MEMBERS.find(candidate=>post.author?.toLowerCase().includes(candidate.name.split(' ')[0].toLowerCase()))||{name:post.author||'Membru Viziunea',email:`${String(post.author||'membru').toLowerCase().replace(/[^a-z0-9]+/g,'.')}@demo.viziunea.ro`,roles:[post.role||'Membru'],interests:post.interest||'Comunitate',city:post.city||'Online'};const roles=Array.isArray(member.roles)?member.roles:[member.roles||'Membru'];const interests=Array.isArray(member.interests)?member.interests: String(member.interests||post.interest||'Comunitate').split(',').map(item=>item.trim()).filter(Boolean);const dialog=document.createElement('dialog');dialog.className='author-profile-dialog';dialog.innerHTML=`<button class="detail-close" type="button" aria-label="Închide">×</button><span class="page-kicker">Profil membru · autorul postării</span><div class="author-profile-identity">${memberAvatarMarkup(member.email,member.name)}<div><h2>${esc(member.name)}</h2><p>${esc(member.email)}</p></div></div><div class="author-profile-meta"><div><strong>Roluri</strong><span>${esc(roles.join(' · '))}</span></div><div><strong>Locație</strong><span>${esc(member.city||post.city||'Online')}</span></div><div><strong>Interese</strong><span>${esc(interests.join(' · '))}</span></div></div>${interestedListMarkup(post,FEED_POSTS.indexOf(post))}<button type="button" class="admin-action" data-author-message>Trimite un mesaj <span>→</span></button>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('.detail-close')?.addEventListener('click',()=>dialog.close());dialog.querySelector('[data-author-message]')?.addEventListener('click',()=>{dialog.close();if(currentUser)openMessageComposer({title:member.name,email:member.email});else go('/auth');});dialog.addEventListener('close',()=>dialog.remove());}
