function enhanceAuthorProfileDialog(){const dialog=document.querySelector('.author-profile-dialog');if(!dialog||dialog.querySelector('.author-profile-details'))return;const name=dialog.querySelector('.author-profile-identity h2')?.textContent.trim()||'';const details=DEMO_MEMBER_DETAILS[name]||{about:'Membru activ în comunitatea Viziunea, interesat de proiecte și colaborări locale.',availability:'Deschis(ă) pentru colaborări',contactMethod:'platform',contactValue:'Mesaj pe Viziunea',links:'Profil public Viziunea'};const button=dialog.querySelector('[data-author-message]');button?.insertAdjacentHTML('beforebegin',`<section class="author-profile-details"><div><strong>Despre</strong><p>${esc(details.about)}</p></div><div><strong>Disponibilitate</strong><p>${esc(details.availability)}</p></div><div><strong>Metodă preferată de contact</strong><p>${esc(details.contactValue)}</p></div><div><strong>Interese</strong><p>Artă · educație · proiecte locale</p></div><div><strong>Linkuri sociale</strong><p class="public-profile-links">${profileLinksMarkup(details.links)}</p></div></section>`);}
function profileLinksMarkup(links){const icons={facebook:'https://s.magecdn.com/social/tc-facebook.svg',instagram:'https://s.magecdn.com/social/tc-instagram.svg',linkedin:'https://s.magecdn.com/social/tc-linkedin.svg',website:'https://s.magecdn.com/social/tc-wordpress.svg'};if(!links)return '';if(typeof links==='string'){const found=[];if(/facebook/i.test(links))found.push(['facebook','https://facebook.com']);if(/linkedin/i.test(links))found.push(['linkedin','https://linkedin.com']);if(/instagram/i.test(links))found.push(['instagram','https://instagram.com']);if(/portofoliu|website|\.ro/i.test(links))found.push(['website','https://viziunea.ro']);return found.map(([key,url])=>`<a href="${url}" target="_blank" rel="noopener" aria-label="${key}"><img src="${icons[key]}" alt="${key}"></a>`).join('');}return Object.entries(links).map(([key,url])=>icons[key]?`<a href="${esc(url)}" target="_blank" rel="noopener" aria-label="${esc(key)}"><img src="${icons[key]}" alt="${esc(key)}"></a>`:'').join('');}
function enhancePublicProfileLinks(){document.querySelectorAll('.author-profile-details').forEach(section=>{const item=[...section.querySelectorAll('div')].find(div=>div.querySelector('strong')?.textContent.toLowerCase().includes('linkuri'));const name=document.querySelector('.author-profile-identity h2,.detail-identity h2')?.textContent.trim();const details=DEMO_MEMBER_DETAILS[name];if(item&&details){const links=item.querySelector('p');const signature=String(details.links||'');if(!links||links.dataset.linksSignature===signature)return;links.classList.add('public-profile-links');links.innerHTML=profileLinksMarkup(details.links);links.dataset.linksSignature=signature;}});}
function removeEmptyPublicLinks(){document.querySelectorAll('.author-profile-details').forEach(section=>{const item=[...section.querySelectorAll('div')].find(div=>div.querySelector('strong')?.textContent.toLowerCase().includes('linkuri'));const links=item?.querySelector('.public-profile-links a');if(item&&!links&&(!item.querySelector('p')?.textContent.trim()||item.querySelector('p')?.textContent.trim()==='Profil public Viziunea'))item.remove();});}
function memberProfileRecord(member={}){const email=String(member.email||'').trim().toLowerCase();let saved={};try{saved=JSON.parse(localStorage.getItem(`viziunea.profile.account.v1:${email}`)||'{}')||{};}catch{}const admin=ADMIN_MEMBERS.find(item=>item.email?.toLowerCase()===email||item.name?.toLowerCase()===String(member.name||'').trim().toLowerCase())||{};return {...admin,...member,...saved,email:email||String(admin.email||'').toLowerCase()};}
function memberSocialLinks(member){const profile=memberProfileRecord(member);const links=profile.profileLinks&&typeof profile.profileLinks==='object'?profile.profileLinks:{};return Object.fromEntries(Object.entries(links).filter(([,url])=>/^https?:\/\//i.test(String(url||''))));}
function memberSocialMarkup(member){const links=memberSocialLinks(member);return Object.keys(links).length?`<section class="author-profile-social"><strong>Linkuri sociale</strong><p class="public-profile-links">${profileLinksMarkup(links)}</p></section>`:'';}
function enhanceInterestedMemberLinks(){document.querySelectorAll('.feed-interested-list li,.profile-interest-crm li').forEach(item=>{if(item.querySelector('[data-interested-member]'))return;const existing=item.querySelector('strong');const name=(existing?.textContent||item.textContent||'Membru Viziunea').trim();const email=item.querySelector('small')?.textContent.trim()||'';const target=existing||item;const button=document.createElement('button');button.type='button';button.className='interested-member-link';button.dataset.interestedMember=name;button.dataset.interestedEmail=email;button.textContent=name;if(existing)existing.replaceWith(button);else{item.textContent='';item.append(button);}});}
function openInterestedMemberProfile(post){const member=memberProfileRecord({name:post.author||'Membru Viziunea',email:post.email||post.author_email});const roles=Array.isArray(member.roles)?member.roles:[member.roles||post.role||'Membru'];const interests=Array.isArray(member.interests)?member.interests:String(member.interests||post.interest||'Comunitate').split(',').map(item=>item.trim()).filter(Boolean);const details=DEMO_MEMBER_DETAILS[member.name]||{};const dialog=document.createElement('dialog');dialog.className='author-profile-dialog';dialog.innerHTML=`<button class="detail-close" type="button" aria-label="Închide">×</button><span class="page-kicker">Profil membru</span><div class="author-profile-identity">${memberAvatarMarkup(member.email,member.name)}<div><h2>${esc(member.name)}</h2><p>${esc(member.email||'')}</p></div></div><div class="author-profile-meta"><div><strong>Roluri</strong><span>${esc(roles.join(' · '))}</span></div><div><strong>Locație</strong><span>${esc(member.city||post.city||'Online')}</span></div><div><strong>Interese</strong><span>${esc(interests.join(' · '))}</span></div></div><section class="author-profile-details"><div><strong>Despre</strong><p>${esc(details.about||'Membru activ în comunitatea Viziunea.')}</p></div><div><strong>Disponibilitate</strong><p>${esc(details.availability||'Deschis(ă) pentru conexiuni în comunitate.')}</p></div>${memberSocialMarkup(member)}</section><button type="button" class="admin-action" data-author-message>Trimite un mesaj <span>→</span></button>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('.detail-close')?.addEventListener('click',()=>dialog.close());dialog.querySelector('[data-author-message]')?.addEventListener('click',()=>{dialog.close();if(currentUser)openMessageComposer({title:member.name,email:member.email});else go('/auth');});dialog.addEventListener('close',()=>dialog.remove());}
function syncAuthorProfileSocial(){document.querySelectorAll('.author-profile-dialog').forEach(dialog=>{const section=dialog.querySelector('.author-profile-details');if(!section||section.dataset.socialReady)return;const name=dialog.querySelector('.author-profile-identity h2')?.textContent.trim()||'';const email=dialog.querySelector('.author-profile-identity p')?.textContent.trim()||'';const social=memberSocialMarkup({name,email});section.querySelector('.author-profile-social')?.remove();section.querySelectorAll('div').forEach(item=>{if(item.querySelector('strong')?.textContent.toLowerCase().includes('linkuri'))item.remove();});if(social)section.insertAdjacentHTML('beforeend',social);section.dataset.socialReady='true';});}
