function enhanceExploreProfileDialog(){const dialog=document.querySelector('.explore-detail-dialog');if(!dialog||dialog.querySelector('.explore-profile-details'))return;const name=dialog.querySelector('.detail-identity h2')?.textContent.trim()||'';const details=DEMO_MEMBER_DETAILS[name]||{about:dialog.querySelector('.detail-identity')?.nextElementSibling?.textContent||'Membru activ în comunitatea Viziunea, interesat de proiecte și colaborări locale.',availability:'Deschis(ă) pentru colaborări',contactMethod:'platform',contactValue:'Mesaj pe Viziunea',links:'Profil public Viziunea'};const old=dialog.querySelector('dl');if(!old)return;old.outerHTML=`<section class="author-profile-details explore-profile-details"><div><strong>Despre</strong><p>${esc(details.about)}</p></div><div><strong>Disponibilitate</strong><p>${esc(details.availability)}</p></div><div><strong>Metodă preferată de contact</strong><p>${esc(details.contactValue)}</p></div><div><strong>Interese</strong><p>Artă · educație · proiecte locale</p></div><div><strong>Linkuri sociale</strong><p class="public-profile-links">${profileLinksMarkup(details.links)}</p></div></section>`;}
