function enhanceFeedHistoryItems(){app.querySelectorAll('.feed-history-item').forEach(item=>{if(item.querySelector('.feed-history-statuses'))return;const index=Number(item.dataset.feedHistoryPost);const post=FEED_POSTS[index];if(!post)return;const postId=postPersistenceId(post,index);const persisted=Boolean(isRealUser()&&/^[0-9a-f-]{36}$/i.test(postId));const saved=isSavedFeedIndex(index);const interested=persisted?serverInterestedPostIds.has(postId):readFeedList(FEED_INTERESTED_KEY).some(row=>row.post_id===postId&&row.profile_id===feedIdentity());const comments=(serverCommentsByPost.get(postId)||listComments(`demo-feed-${index}`)).length;const details=[];if(interested)details.push('Interesat');if(saved)details.push('Salvată');if(comments)details.push(`${comments} ${comments===1?'comentariu':'comentarii'}`);if(!details.length)details.push('Fără acțiuni');const meta=item.querySelector('span:nth-child(2)');if(meta)meta.insertAdjacentHTML('beforeend',`<span class="feed-history-statuses">${details.map(detail=>`<b>${esc(detail)}</b>`).join('')}</span>`);});}
/* The history detail keeps the complete context of the interaction, not just the post copy. */
function openFeedPostDetail(post){const index=FEED_POSTS.indexOf(post);const postId=postPersistenceId(post,index);const author=ADMIN_MEMBERS.find(member=>post.author?.toLowerCase().includes(member.name.split(' ')[0].toLowerCase()))||{name:post.author,email:`${String(post.author||'membru').toLowerCase().replace(/[^a-z0-9]+/g,'.')}@demo.viziunea.ro`};const persisted=Boolean(isRealUser()&&/^[0-9a-f-]{36}$/i.test(postId));const saved=isSavedFeedIndex(index);const liked=persisted?serverLikedPostIds.has(postId):readFeedList(FEED_LIKES_KEY).some(row=>row.post_id===postId&&row.profile_id===feedIdentity());const interested=persisted?serverInterestedPostIds.has(postId):readFeedList(FEED_INTERESTED_KEY).some(row=>row.post_id===postId&&row.profile_id===feedIdentity());const comments=(serverCommentsByPost.get(postId)||listComments(`demo-feed-${index}`)).map(comment=>persisted?normalizeServerComment(comment):comment);const status=(active,label,icon)=>`<span class="feed-detail-status ${active?'is-active':''}"><b>${icon}</b><span>${active?label:`Nu ${label.toLowerCase()}`}</span></span>`;const dialog=document.createElement('dialog');dialog.className='feed-post-detail-dialog';dialog.innerHTML=`<button class="detail-close" type="button" aria-label="Închide">×</button>${post.image_url||DEMO_FEED_IMAGES[index]?`<img src="${esc(post.image_url||DEMO_FEED_IMAGES[index])}" alt="Imagine reprezentativă">`:''}<span class="page-kicker">${esc(post.interest||'Comunitate')} · postare în Feed</span><h2>${esc(post.title)}</h2><div class="feed-detail-author"><span class="feed-post-avatar">${esc(post.initial||post.author?.[0]||'M')}</span><div><strong>${esc(post.author||'Membru Viziunea')}</strong><small>${esc(post.role||'Membru')} · ${esc(post.city||'Online')} · ${esc(post.time||'')}</small></div></div><p class="feed-detail-body">${esc(post.body)}</p><div class="feed-detail-tags">${feedPostInterests(post).map(interest=>`<span>${esc(interest)}</span>`).join('')}</div><section class="feed-detail-status-grid" aria-label="Activitatea ta la această postare">${status(interested,'Ești interesat','✓')}${status(saved,'Salvată de tine','♡')}${status(liked,'Ai exprimat entuziasm','🤩')}<span class="feed-detail-status"><b>💬</b><span>${comments.length} ${comments.length===1?'comentariu':'comentarii'}</span></span></section>${comments.length?`<section class="feed-detail-comments"><header><strong>Conversația de aici</strong><span>${comments.length}</span></header><div class="feed-comment-list">${renderCommentTree(comments)}</div></section>`:'<p class="feed-detail-no-comments">Încă nu există comentarii la această postare.</p>'}<button type="button" class="admin-action" data-feed-detail-cta>${esc(post.action||'Contactează autorul')} <span>→</span></button><p class="feed-detail-notice"></p>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('.detail-close')?.addEventListener('click',()=>dialog.close());dialog.querySelector('[data-feed-detail-cta]')?.addEventListener('click',()=>{if(currentUser){dialog.close();openMessageComposer({title:author.name,email:author.email});}else{dialog.querySelector('.feed-detail-notice').textContent='Intră în cont pentru a putea contacta autorul.';}});dialog.addEventListener('close',()=>dialog.remove());}
document.addEventListener('click',event=>{const saved=event.target.closest?.('[data-saved-post]');if(!saved||event.target.closest('[data-remove-saved],[data-saved-toggle]'))return;const post=FEED_POSTS[Number(saved.dataset.savedPost)];if(post)openFeedPostDetail(post);});
document.addEventListener('click',event=>{if(path()!=='/profil'||!event.target.closest?.('[data-profile-tab]'))return;const scrollY=window.scrollY;requestAnimationFrame(()=>{stabilizeProfileTabHeight();window.scrollTo({top:scrollY,left:0,behavior:'auto'});});},true);
document.addEventListener('click',event=>{const tab=event.target.closest?.('[data-profile-tab]');if(path()!=='/profil'||!tab)return;const key=tab.dataset.profileTab;app.querySelectorAll('.profile-selectors>article').forEach(panel=>panel.classList.toggle('is-tab-hidden',!panel.classList.contains(key)));app.querySelectorAll('[data-profile-tab]').forEach(item=>{const active=item===tab;item.classList.toggle('is-active',active);item.setAttribute('aria-selected',active);});});
app.addEventListener('change',event=>{if(path()==='/exploreaza'&&event.target.matches('.explore-filter')){exploreFilters[event.target.dataset.filter]=event.target.value;saveExploreFilters();}if(path()==='/profil'&&event.target.matches('[data-profile-defaults]')){demoProfile.useProfileDefaults=event.target.checked;saveProfileDemo(demoProfile);void saveProfileToSupabase(demoProfile,currentUser).catch(error=>console.warn('Profile defaults sync failed',error));}});
app.addEventListener('change',event=>{if(path()!=='/profil'||!event.target.matches('[data-profile-defaults]')||event.target.checked)return;Object.keys(exploreFilters).forEach(key=>exploreFilters[key]='');saveExploreFilters();});
app.addEventListener('input',event=>{if(path()!=='/profil'||!event.target.matches('[data-profile-field]'))return;const key={contact:'profileContact',about:'profileAbout',availabilityDetails:'profileAvailabilityDetails',links:'profileLinks'}[event.target.dataset.profileField];if(!key)return;demoProfile[key]=event.target.value;saveProfileDemo(demoProfile);void saveProfileToSupabase(demoProfile,currentUser).catch(error=>console.warn('Profile details sync failed',error));});
app.addEventListener('change',event=>{if(path()!=='/profil')return;const check=event.target.closest('[data-profile-link-check]');const link=event.target.closest('[data-profile-link]');if(!check&&!link)return;const key=(check||link).dataset.profileLinkCheck||(check||link).dataset.profileLink;const input=app.querySelector(`[data-profile-link="${key}"]`);if(check){input.hidden=!check.checked;if(!check.checked)input.value='';}const links={};app.querySelectorAll('[data-profile-link]').forEach(item=>{if(item.value.trim())links[item.dataset.profileLink]=item.value.trim();});demoProfile.profileLinks=links;saveProfileDemo(demoProfile);void saveProfileToSupabase(demoProfile,currentUser).catch(error=>console.warn('Profile links sync failed',error));});
app.addEventListener('change',event=>{if(path()!=='/profil')return;const method=event.target.closest('[data-profile-contact-method]');const phone=event.target.closest('[data-profile-contact-phone]');if(!method&&!phone)return;if(method){demoProfile.profileContactMethod=method.value;const phoneInput=app.querySelector('[data-profile-contact-phone]');if(phoneInput)phoneInput.hidden=method.value!=='whatsapp';}if(phone)demoProfile.profileContactPhone=phone.value;saveProfileDemo(demoProfile);void saveProfileToSupabase(demoProfile,currentUser).catch(error=>console.warn('Profile contact sync failed',error));});
app.addEventListener('click',event=>{if(path()!=='/profil')return;const method=event.target.closest('[data-profile-contact-method]');if(!method)return;const value=method.dataset.profileContactMethod;demoProfile.profileContactMethod=value;app.querySelectorAll('[data-profile-contact-method]').forEach(item=>item.classList.toggle('is-active',item===method));const fields=app.querySelector('.profile-whatsapp-fields');if(fields)fields.hidden=value!=='whatsapp';saveProfileDemo(demoProfile);void saveProfileToSupabase(demoProfile,currentUser).catch(error=>console.warn('Profile contact sync failed',error));});
app.addEventListener('change',event=>{if(path()!=='/profil')return;const phone=event.target.closest('[data-profile-contact-phone]');const consent=event.target.closest('[data-profile-contact-public]');if(!phone&&!consent)return;if(phone)demoProfile.profileContactPhone=phone.value;if(consent)demoProfile.profileContactPublic=consent.checked;saveProfileDemo(demoProfile);void saveProfileToSupabase(demoProfile,currentUser).catch(error=>console.warn('Profile contact sync failed',error));});
app.addEventListener('change',event=>{if(path()!=='/profil'||!event.target.matches('[data-profile-field="availability"]'))return;const details=event.target.closest('.profile-availability')?.querySelector('[data-profile-field="availabilityDetails"]');if(details){details.hidden=!event.target.checked;if(!event.target.checked){details.value='';demoProfile.profileAvailabilityDetails='';}}demoProfile.profileAvailability=event.target.checked;saveProfileDemo(demoProfile);void saveProfileToSupabase(demoProfile,currentUser).catch(error=>console.warn('Profile availability sync failed',error));});
app.addEventListener('change',event=>{if(path()!=='/profil'||!event.target.matches('[data-profile-image]'))return;const control=event.target.closest('.profile-image-control');const file=event.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){event.target.value='';return;}control?.classList.add('is-uploading');const reader=new FileReader();reader.onload=()=>{const dataUrl=String(reader.result);setProfileAvatar(dataUrl);delete demoProfile.avatarUrl;saveProfileDemo(demoProfile);void saveProfileToSupabase(demoProfile,currentUser).catch(error=>console.warn('Profile image sync failed',error));const avatar=app.querySelector('.profile-hero .large-avatar');if(avatar){avatar.innerHTML=`<img src="${esc(dataUrl)}" alt="Imagine de profil">`;avatar.classList.add('has-profile-image');}syncNavbarAvatar();control?.classList.remove('is-uploading');event.target.blur();};reader.onerror=()=>control?.classList.remove('is-uploading');reader.readAsDataURL(file);});
new MutationObserver(()=>{syncProfileIdentity();syncNavbarAvatar();enhanceProfileDefaults();enhanceProfileImage();arrangeProfileGrid();enhanceProfileSummary();enhanceProfileNewsLink();seedOwnProfileDetails();enhanceProfileLinks();moveProfileContact();enhanceContactPreferences();restoreProfileSummaryFields();restoreProfileAvailability();restoreProfileLinks();enhanceProfileTabs();enhanceProfileContactMethods();arrangeProfileDetails();stabilizeProfileTabHeight();applyExploreSavedControls();}).observe(app,{childList:true});
new MutationObserver(()=>{enhanceInterestedMemberLinks();enhanceAuthorProfileDialog();enhanceExploreProfileDialog();enhancePublicProfileLinks();removeEmptyPublicLinks();syncAuthorProfileSocial();removePeoplePublisherLabels();}).observe(document.body,{childList:true,subtree:true});
app.addEventListener('click',event=>{if(path()!=='/profil')return;const text=event.target.closest('.profile-checkbox-row>span');if(!text)return;const checkbox=text.parentElement.querySelector('input[type="checkbox"]');if(!checkbox)return;checkbox.checked=!checkbox.checked;checkbox.dispatchEvent(new Event('change',{bubbles:true}));});
